-- ContrataCR Pro, database part 10 of 21 (PRO_ENABLED stays false: nothing here turns Pro on).
-- Generated by scripts/pro/build-pro-migrations.mjs from the ordered local SQL manifest (scripts/pro/local-sql-manifest.mjs);
-- do not edit by hand: change docs/pro/sql and regenerate. Every module is idempotent (create if not exists / or replace /
-- guarded blocks) and keeps its own RLS, grants (service_role only unless stated) and pinned search_path.
-- Modules, in order:
--   lead-inboxes-local.sql sha256:9d2da38de255
--   company-vendors-local.sql sha256:047c510e1932
--   takeoffs-local.sql sha256:be98ffff1874
--   credits-retainers-local.sql sha256:bf45a7558d67
--   credits-retainers-guard-local.sql sha256:7fe48781f67c
-- ===== lead-inboxes-local.sql =====
-- LOCAL PRO ONLY. Lead inboxes: private snooze, CSV import ledger, inbox reader and funnel.
-- Reuses the existing private writers (pro_lead_origin_create, pro_lead_private_core_mutate,
-- pro_mutate_catalog). No old function, table, trigger, payload or receipt is changed.
-- Snooze expiry is computed on read in Costa Rica time: there is no cron or backfill.
begin;
create table if not exists public.pro_lead_snoozes(
 owner_id uuid not null references profiles(id) on delete cascade,
 kind text not null check(kind in('manual','request')),
 id uuid not null,
 manual_kind text not null default 'manual' check(manual_kind='manual'),
 manual_id uuid,
 request_id uuid,
 until_date date,
 note text not null default '' check(length(note)<=500),
 active boolean not null default false,
 revision integer not null check(revision>0),
 updated_at timestamptz not null default now(),
 primary key(owner_id,kind,id),
 foreign key(owner_id,manual_kind,manual_id) references pro_lead_center_records(owner_id,kind,id) on delete cascade,
 foreign key(owner_id,request_id) references pro_appointment_requests(owner_id,id) on delete cascade,
 check(case when kind='manual' then manual_id=id and request_id is null else request_id=id and manual_id is null end),
 check(not active or until_date is not null),
 check(until_date is null or until_date between date'2000-01-01' and date'2100-12-31'));
create table if not exists public.pro_lead_snooze_history(
 owner_id uuid not null,kind text not null,id uuid not null,action_id uuid not null,
 action text not null check(action in('snooze','wake')),
 before_state jsonb not null,after_state jsonb not null,at timestamptz not null default now(),
 primary key(owner_id,action_id),
 foreign key(owner_id,kind,id) references pro_lead_snoozes(owner_id,kind,id) on delete cascade);
create index if not exists pro_lead_snooze_history_page on public.pro_lead_snooze_history(owner_id,kind,id,((after_state->>'revision')::integer) desc);
create table if not exists public.pro_lead_inbox_actions(
 owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,
 kind text not null check(kind in('snooze','wake','import','undo_import')),
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),
 primary key(owner_id,action_id));
create table if not exists public.pro_lead_imports(
 owner_id uuid not null references profiles(id) on delete cascade,id uuid not null,
 file_name text not null check(length(file_name) between 1 and 160),
 total_rows integer not null check(total_rows between 1 and 200),
 created_leads integer not null default 0,created_clients integer not null default 0,
 reused_clients integer not null default 0,skipped_duplicates integer not null default 0,
 revision integer not null default 1 check(revision>0),
 undone_at timestamptz,undo_action_id uuid,archived_on_undo integer,
 created_at timestamptz not null default now(),
 primary key(owner_id,id),
 check((undone_at is null)=(undo_action_id is null) and (undone_at is null)=(archived_on_undo is null)));
create index if not exists pro_lead_imports_page on public.pro_lead_imports(owner_id,created_at desc,id desc);
create table if not exists public.pro_lead_import_rows(
 owner_id uuid not null,import_id uuid not null,row_number integer not null check(row_number between 1 and 200),
 status text not null check(status in('created','existing_client','duplicate')),
 lead_kind text not null default 'manual' check(lead_kind='manual'),lead_id uuid,client_id text not null,
 client_created boolean not null default false,
 primary key(owner_id,import_id,row_number),
 foreign key(owner_id,import_id) references pro_lead_imports(owner_id,id) on delete cascade,
 foreign key(owner_id,lead_kind,lead_id) references pro_lead_center_records(owner_id,kind,id) on delete cascade,
 check((status='duplicate')=(lead_id is null)),check(not client_created or status='created'));

create or replace function public.pro_lead_inbox_today() returns date language sql stable security invoker set search_path=public,pg_temp as $$select (now() at time zone 'America/Costa_Rica')::date$$;
create or replace function public.pro_lead_snooze_json(p_actor uuid,p_kind text,p_id uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('kind',p_kind,'id',p_id,'revision',coalesce(s.revision,0),'active',coalesce(s.active,false),
  'until',case when s.active then to_char(s.until_date,'YYYY-MM-DD') else null end,'note',case when s.active then s.note else '' end,
  'snoozed',coalesce(s.active and s.until_date>pro_lead_inbox_today(),false),'updatedAt',s.updated_at)
 from(select 1)d left join pro_lead_snoozes s on s.owner_id=p_actor and s.kind=p_kind and s.id=p_id$$;
create or replace function public.pro_lead_snooze_read(p_actor uuid,p_kind text,p_id uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare items jsonb;begin
 perform pro_lead_origin_owner(p_actor);perform pro_lead_origin_item(p_actor,p_kind,p_id);
 select coalesce(jsonb_agg(jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_state,'after',h.after_state) order by (h.after_state->>'revision')::integer desc),'[]') into items
 from(select * from pro_lead_snooze_history where owner_id=p_actor and kind=p_kind and id=p_id order by (after_state->>'revision')::integer desc limit 20)h;
 return jsonb_build_object('snooze',pro_lead_snooze_json(p_actor,p_kind,p_id),'history',items);end $$;
create or replace function public.pro_lead_inbox_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_inbox_actions;begin
 perform pro_lead_origin_owner(p_actor);select * into r from pro_lead_inbox_actions where owner_id=p_actor and action_id=p_action;
 if not found then return jsonb_build_object('receipt',null);end if;return jsonb_build_object('receipt',jsonb_build_object('kind',r.kind,'input',r.input,'result',r.result));end $$;

-- Snooze/wake: one optimistic revision per lead; archived leads must be restored first.
create or replace function public.pro_lead_inbox_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;act text;k text;lid uuid;rev integer;prior pro_lead_inbox_actions;s pro_lead_snoozes;had boolean;item jsonb;archived boolean;until_value date;note_value text;before_json jsonb;after_json jsonb;answer jsonb;today date:=pro_lead_inbox_today();begin
 perform pro_lead_origin_owner(p_actor);
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'kind') is distinct from 'string' or jsonb_typeof(p_input->'id') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid snooze action' using errcode='22023';end if;
 act:=p_input->>'action';k:=p_input->>'kind';aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'id')::uuid;rev:=(p_input->>'revision')::integer;
 if act not in('snooze','wake') or k not in('manual','request') or (select array_agg(key order by key collate "C") from jsonb_object_keys(p_input)key) is distinct from (case act when 'snooze' then array['action','actionId','id','kind','note','revision','until'] else array['action','actionId','id','kind','revision'] end) then raise exception 'Invalid snooze fields' using errcode='22023';end if;
 if act='snooze' then
  if jsonb_typeof(p_input->'until') is distinct from 'string' or not(p_input->>'until'~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$') or jsonb_typeof(p_input->'note') is distinct from 'string' then raise exception 'Invalid snooze date' using errcode='22023';end if;
  begin until_value:=(p_input->>'until')::date;exception when others then raise exception 'Invalid snooze date' using errcode='22023';end;
  note_value:=btrim(p_input->>'note');if length(note_value)>500 or regexp_replace(note_value,E'[\\n\\r\\t]','','g')~'[[:cntrl:]]' then raise exception 'Invalid snooze note' using errcode='22023';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-inbox-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-snooze:'||p_actor::text||':'||k||':'||lid::text,0));perform pro_lead_origin_owner(p_actor);
 select * into prior from pro_lead_inbox_actions where owner_id=p_actor and action_id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Snooze action reused' using errcode='22023';end if;perform pro_lead_origin_item(p_actor,k,lid);return prior.result;end if;
 item:=pro_lead_origin_item(p_actor,k,lid);
 archived:=case when k='manual' then (item->'manual'->>'archived')::boolean else (item->'preference'->>'archived')::boolean end;
 select * into s from pro_lead_snoozes where owner_id=p_actor and kind=k and id=lid for update;had:=found;
 if coalesce(s.revision,0)<>rev then raise exception 'Snooze changed' using errcode='40001';end if;
 before_json:=pro_lead_snooze_json(p_actor,k,lid);
 if act='snooze' then
  if archived then raise exception 'Restore before snoozing' using errcode='40001';end if;
  if until_value<=today or until_value>today+366 then raise exception 'Snooze date must be after today and within a year' using errcode='22023';end if;
  if rev>=2147483646 then raise exception 'Snooze revision exhausted' using errcode='40001';end if;
  insert into pro_lead_snoozes(owner_id,kind,id,manual_id,request_id,until_date,note,active,revision) values(p_actor,k,lid,case when k='manual' then lid end,case when k='request' then lid end,until_value,note_value,true,rev+1)
  on conflict(owner_id,kind,id) do update set until_date=excluded.until_date,note=excluded.note,active=true,revision=excluded.revision,updated_at=now();
 else
  if not had or not s.active then raise exception 'Lead is not snoozed' using errcode='40001';end if;
  update pro_lead_snoozes set active=false,revision=revision+1,updated_at=now() where owner_id=p_actor and kind=k and id=lid;
 end if;
 after_json:=pro_lead_snooze_json(p_actor,k,lid);
 insert into pro_lead_snooze_history(owner_id,kind,id,action_id,action,before_state,after_state) values(p_actor,k,lid,aid,act,before_json,after_json);
 answer:=jsonb_build_object('action',act,'snooze',after_json,'before',before_json);
 insert into pro_lead_inbox_actions(owner_id,action_id,kind,input,result) values(p_actor,aid,act,p_input,answer);return answer;end $$;

-- Deterministic RFC 4122 version-4 shaped identity for each child of one import action.
create or replace function public.pro_lead_import_uuid(p_seed text) returns uuid language sql immutable security invoker set search_path=public,pg_temp as $$
 select (substr(h,1,12)||'4'||substr(h,14,3)||substr('89ab',(get_byte(decode(substr(h,17,2),'hex'),0)%4)+1,1)||substr(h,18,15))::uuid from(select md5(p_seed)h)x$$;
-- Phone comparison key: digits only; Costa Rica country prefix 506 is dropped from 11 digits.
create or replace function public.pro_lead_import_phone_key(p text) returns text language sql immutable security invoker set search_path=public,pg_temp as $$
 select case when length(d)=11 and left(d,3)='506' then right(d,8) when length(d) between 8 and 15 then d else '' end from(select regexp_replace(coalesce(p,''),'[^0-9]','','g')d)x$$;
-- Row analysis only compares with this owner's own customers and requests.
create or replace function public.pro_lead_import_analyze(p_actor uuid,p_rows jsonb) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r jsonb;n integer:=0;result jsonb:='[]';errs text[];name_v text;email_v text;phone_v text;service_v text;type_v text;channel_v text;address_v text;desc_v text;ekey text;pkey text;seen_e text[]:='{}';seen_p text[]:='{}';c pro_clients;matched boolean;status_v text;channel_id text;channel_rev integer;begin
 perform pro_lead_origin_owner(p_actor);
 if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 200 then raise exception 'Invalid import rows' using errcode='22023';end if;
 for r in select value from jsonb_array_elements(p_rows) loop
  n:=n+1;
  if jsonb_typeof(r) is distinct from 'object' or (select array_agg(key order by key collate "C") from jsonb_object_keys(r)key) is distinct from array['address','channel','description','email','name','phone','projectType','service'] or exists(select 1 from jsonb_each(r)e where jsonb_typeof(e.value)<>'string') then raise exception 'Invalid import row' using errcode='22023';end if;
  errs:='{}';name_v:=btrim(r->>'name');email_v:=lower(btrim(r->>'email'));phone_v:=btrim(r->>'phone');service_v:=btrim(r->>'service');type_v:=btrim(r->>'projectType');channel_v:=btrim(r->>'channel');address_v:=btrim(r->>'address');desc_v:=btrim(r->>'description');
  if name_v='' then errs:=errs||'name_required'::text;elsif length(name_v)>160 then errs:=errs||'name_too_long'::text;end if;
  if service_v='' then errs:=errs||'service_required'::text;elsif length(service_v)>160 then errs:=errs||'service_too_long'::text;end if;
  if email_v='' and phone_v='' then errs:=errs||'contact_required'::text;end if;
  if email_v<>'' and(length(email_v)>254 or email_v!~'^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$')then errs:=errs||'email_invalid'::text;end if;
  if phone_v<>'' and(length(phone_v)>30 or phone_v!~'^[+0-9 ().-]+$' or length(regexp_replace(phone_v,'[^0-9]','','g'))not between 8 and 15)then errs:=errs||'phone_invalid'::text;end if;
  if length(type_v)>80 then errs:=errs||'project_type_too_long'::text;end if;
  if length(address_v)>500 then errs:=errs||'address_too_long'::text;end if;
  if length(desc_v)>2000 then errs:=errs||'description_too_long'::text;end if;
  if (name_v||email_v||phone_v||service_v||type_v||channel_v||address_v)~'[[:cntrl:]]' or regexp_replace(desc_v,E'[\\n\\r\\t]','','g')~'[[:cntrl:]]' then errs:=errs||'invalid_characters'::text;end if;
  ekey:=case when email_v<>'' and not('email_invalid'=any(errs)) then email_v else '' end;pkey:=case when phone_v<>'' and not('phone_invalid'=any(errs)) then pro_lead_import_phone_key(phone_v) else '' end;
  if ekey<>'' and ekey=any(seen_e) or pkey<>'' and pkey=any(seen_p) then errs:=errs||'duplicate_in_file'::text;end if;
  if ekey<>'' then seen_e:=seen_e||ekey;end if;if pkey<>'' then seen_p:=seen_p||pkey;end if;
  channel_id:=null;channel_rev:=null;
  if channel_v<>'' then select x.id,x.revision into channel_id,channel_rev from pro_lead_origin_catalog(p_actor)x where not x.archived and lower(channel_v)=any(pro_lead_origin_name_aliases(x.id,x.name,x.custom_name)) order by x.builtin desc,x.id limit 1;if channel_id is null then errs:=errs||'channel_unknown'::text;end if;end if;
  matched:=false;
  if ekey<>'' or pkey<>'' then
   select * into c from pro_clients pc where pc.user_id=p_actor and(ekey<>'' and lower(btrim(pc.email))=ekey or pkey<>'' and pro_lead_import_phone_key(pc.phone)=pkey) order by(ekey<>'' and lower(btrim(pc.email))=ekey) desc,pc.archived,pc.position limit 1;matched:=found;
  end if;
  status_v:='new';
  if matched then
   status_v:='existing_client';if c.archived then errs:=errs||'client_archived'::text;end if;
   if service_v<>'' and(exists(select 1 from pro_lead_center_records l where l.owner_id=p_actor and l.kind='manual' and l.client_id=c.id and not l.archived and lower(btrim(l.title))=lower(service_v))
    or exists(select 1 from pro_appointment_requests q left join pro_lead_center_records pref on pref.owner_id=p_actor and pref.kind='request' and pref.id=q.id where q.owner_id=p_actor and c.id='reservation-'||q.client_user_id::text and not coalesce(pref.archived,false) and lower(btrim(q.service))=lower(service_v))) then status_v:='duplicate';end if;
  end if;
  if cardinality(errs)>0 then status_v:='error';end if;
  result:=result||jsonb_build_array(jsonb_build_object('row',n,'status',status_v,'errors',to_jsonb(errs),'name',left(name_v,160),'service',left(service_v,160),
   'client',case when matched then jsonb_build_object('id',c.id,'name',c.name,'archived',c.archived) else null end,
   'channel',case when channel_id is null then null else jsonb_build_object('id',channel_id,'revision',channel_rev) end));
 end loop;return result;end $$;
create or replace function public.pro_lead_import_summary(p_analysis jsonb) returns jsonb language sql immutable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('total',count(*),'new',count(*) filter(where a->>'status'='new'),'existingClient',count(*) filter(where a->>'status'='existing_client'),'duplicate',count(*) filter(where a->>'status'='duplicate'),'error',count(*) filter(where a->>'status'='error')) from jsonb_array_elements(p_analysis)a$$;
create or replace function public.pro_lead_import_preview(p_actor uuid,p_rows jsonb) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare analysis jsonb;begin
 analysis:=pro_lead_import_analyze(p_actor,p_rows);return jsonb_build_object('rows',analysis,'summary',pro_lead_import_summary(analysis));end $$;
create or replace function public.pro_lead_import_json(p_actor uuid,p_id uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',i.id,'fileName',i.file_name,'totalRows',i.total_rows,'createdLeads',i.created_leads,'createdClients',i.created_clients,'reusedClients',i.reused_clients,'skippedDuplicates',i.skipped_duplicates,'revision',i.revision,'createdAt',i.created_at,'undoneAt',i.undone_at,'archivedOnUndo',i.archived_on_undo,
  'activeLeads',(select count(*) from pro_lead_import_rows x join pro_lead_center_records l on l.owner_id=x.owner_id and l.kind='manual' and l.id=x.lead_id where x.owner_id=i.owner_id and x.import_id=i.id and not l.archived))
 from pro_lead_imports i where i.owner_id=p_actor and i.id=p_id$$;
create or replace function public.pro_lead_imports_read(p_actor uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare anchor timestamptz;items jsonb;next_id uuid;begin
 perform pro_lead_origin_owner(p_actor);
 if p_after is not null then select created_at into anchor from pro_lead_imports where owner_id=p_actor and id=p_after;if not found then raise exception 'Import history changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(pro_lead_import_json(p_actor,x.id) order by x.created_at desc,x.id desc),'[]') into items from(select id,created_at from pro_lead_imports where owner_id=p_actor and(p_after is null or(created_at,id)<(anchor,p_after)) order by created_at desc,id desc limit 21)x;
 if jsonb_array_length(items)>20 then next_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',next_id,'total',(select count(*) from pro_lead_imports where owner_id=p_actor));end $$;

-- Atomic CSV import and safe undo. Undo archives (never deletes) the leads that this import
-- created and that are still active and untouched; customers created by the import are kept.
create or replace function public.pro_lead_import_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;act text;prior pro_lead_inbox_actions;analysis jsonb;a jsonb;rows_v jsonb;row_v jsonb;v integer;new_clients jsonb:='[]';cid text;lid uuid;cat integer;created integer:=0;made integer:=0;reused integer:=0;skipped integer:=0;answer jsonb;imp pro_lead_imports;fname text;iid uuid;rev integer;archived_count integer:=0;rec pro_lead_center_records;ir pro_lead_import_rows;n text;begin
 perform pro_lead_origin_owner(p_actor);
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' then raise exception 'Invalid import action' using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;
 if act not in('import','undo_import') or (select array_agg(key order by key collate "C") from jsonb_object_keys(p_input)key) is distinct from (case act when 'import' then array['action','actionId','fileName','rows'] else array['action','actionId','importId','revision'] end) then raise exception 'Invalid import fields' using errcode='22023';end if;
 if act='import' then
  if jsonb_typeof(p_input->'fileName') is distinct from 'string' then raise exception 'Invalid file name' using errcode='22023';end if;fname:=btrim(p_input->>'fileName');
  if length(fname) not between 1 and 160 or fname~'[[:cntrl:]]' then raise exception 'Invalid file name' using errcode='22023';end if;
  rows_v:=p_input->'rows';if jsonb_typeof(rows_v) is distinct from 'array' or jsonb_array_length(rows_v) not between 1 and 200 then raise exception 'Invalid import rows' using errcode='22023';end if;
 else
  if jsonb_typeof(p_input->'importId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646 then raise exception 'Invalid undo' using errcode='22023';end if;
  iid:=(p_input->>'importId')::uuid;rev:=(p_input->>'revision')::integer;
 end if;
 -- Owner lock first, as every private lead/customer writer; then catalogue locks.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-inbox-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select * into prior from pro_lead_inbox_actions where owner_id=p_actor and action_id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Import action reused' using errcode='22023';end if;return prior.result;end if;
 if act='import' then
  if exists(select 1 from pro_lead_imports where owner_id=p_actor and id=aid) then raise exception 'Import identity used' using errcode='40001';end if;
  analysis:=pro_lead_import_analyze(p_actor,rows_v);
  if exists(select 1 from jsonb_array_elements(analysis)x,jsonb_array_elements_text(x->'errors')e where e not in('channel_unknown','client_archived')) then raise exception 'Import has invalid rows' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(analysis)x where x->>'status'='error') then raise exception 'Import data changed; review the preview' using errcode='40001';end if;
  for a in select value from jsonb_array_elements(analysis) loop
   if a->>'status'='new' then n:=a->>'row';row_v:=rows_v->((a->>'row')::integer-1);
    new_clients:=new_clients||jsonb_build_array(jsonb_build_object('id',pro_lead_import_uuid(aid::text||':client:'||n)::text,'name',btrim(row_v->>'name'),'email',lower(btrim(row_v->>'email')),'phone',btrim(row_v->>'phone'),'notes','','archived',false));
   end if;
  end loop;
  if jsonb_array_length(new_clients)>0 then select revision into v from pro_workspace_core where user_id=p_actor for update;perform pro_mutate_catalog(p_actor,'clients',new_clients,coalesce(v,0),'[]'::jsonb,true);made:=jsonb_array_length(new_clients);end if;
  insert into pro_lead_imports(owner_id,id,file_name,total_rows) values(p_actor,aid,fname,jsonb_array_length(rows_v));
  cat:=(pro_lead_origin_stage_catalog(p_actor)->>'revision')::integer;
  for a in select value from jsonb_array_elements(analysis) loop
   n:=a->>'row';row_v:=rows_v->((a->>'row')::integer-1);
   cid:=case when a->>'status'='new' then pro_lead_import_uuid(aid::text||':client:'||n)::text else a->'client'->>'id' end;
   if a->>'status' in('new','existing_client') then
    lid:=pro_lead_import_uuid(aid::text||':lead:'||n);
    perform pro_lead_origin_create(p_actor,jsonb_build_object('action','create_lead','actionId',pro_lead_import_uuid(aid::text||':parent:'||n),
     'lead',jsonb_build_object('action','create','actionId',pro_lead_import_uuid(aid::text||':core:'||n),'kind','manual','id',lid,'revision',0,'catalogRevision',cat,'clientId',cid,'title',btrim(row_v->>'service'),'description',btrim(row_v->>'description'),'address',btrim(row_v->>'address'),'sourceLabel','',
      'forecast',jsonb_build_object('projectType',btrim(row_v->>'projectType'),'expectedStart',null,'currency','CRC','revenueCents',null,'budgetCents',null,'profitCents',null),'stageMode','automatic','stageId',null),
     'channel',coalesce(a->'channel','null'::jsonb)));
    insert into pro_lead_import_rows(owner_id,import_id,row_number,status,lead_id,client_id,client_created) values(p_actor,aid,n::integer,case when a->>'status'='new' then 'created' else 'existing_client' end,lid,cid,a->>'status'='new');
    created:=created+1;if a->>'status'='existing_client' then reused:=reused+1;end if;
   else
    insert into pro_lead_import_rows(owner_id,import_id,row_number,status,lead_id,client_id) values(p_actor,aid,n::integer,'duplicate',null,cid);skipped:=skipped+1;
   end if;
  end loop;
  update pro_lead_imports set created_leads=created,created_clients=made,reused_clients=reused,skipped_duplicates=skipped where owner_id=p_actor and id=aid;
  perform pro_lead_origin_owner(p_actor);
  answer:=jsonb_build_object('action','import','import',pro_lead_import_json(p_actor,aid),'summary',pro_lead_import_summary(analysis));
 else
  select * into imp from pro_lead_imports where owner_id=p_actor and id=iid for update;
  if not found then raise exception 'Import unavailable' using errcode='P0002';end if;
  if imp.revision<>rev or imp.undone_at is not null then raise exception 'Import changed' using errcode='40001';end if;
  for ir in select * from pro_lead_import_rows where owner_id=p_actor and import_id=iid and lead_id is not null order by row_number loop
   select * into rec from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=ir.lead_id for update;
   -- Only untouched leads are archived: same core revision as created (1), no work/quote link,
   -- follow-up, snooze or channel change after the import. Converted or edited leads are kept.
   if found and not rec.archived and rec.revision=1
    and not exists(select 1 from pro_manual_lead_works w where w.owner_id=p_actor and w.lead_kind='manual' and w.lead_id=ir.lead_id)
    and not exists(select 1 from pro_manual_lead_quotes w where w.owner_id=p_actor and w.lead_kind='manual' and w.lead_id=ir.lead_id)
    and not exists(select 1 from pro_lead_followups w where w.owner_id=p_actor and w.lead_kind='manual' and w.lead_id=ir.lead_id)
    and not exists(select 1 from pro_lead_snoozes w where w.owner_id=p_actor and w.kind='manual' and w.id=ir.lead_id)
    and not exists(select 1 from pro_lead_origin_history w where w.owner_id=p_actor and w.kind='manual' and w.id=ir.lead_id and w.action_id<>pro_lead_import_uuid(iid::text||':parent:'||ir.row_number)) then
    perform pro_lead_private_core_mutate(p_actor,jsonb_build_object('action','archive','actionId',pro_lead_import_uuid(aid::text||':archive:'||ir.row_number),'kind','manual','id',ir.lead_id,'revision',rec.revision));archived_count:=archived_count+1;
   end if;
  end loop;
  update pro_lead_imports set undone_at=now(),undo_action_id=aid,archived_on_undo=archived_count,revision=revision+1 where owner_id=p_actor and id=iid;
  answer:=jsonb_build_object('action','undo_import','import',pro_lead_import_json(p_actor,iid),'archived',archived_count);
 end if;
 insert into pro_lead_inbox_actions(owner_id,action_id,kind,input,result) values(p_actor,aid,act,p_input,answer);return answer;end $$;

-- Inbox reader: same page/context/stage envelope as pro_lead_commercial_read, plus snooze
-- state per row, server counters for every inbox (same main filters) and the service facet.
create or replace function public.pro_lead_inbox_sources(p_actor uuid,p_query text) returns table(kind text,id uuid,created_at timestamptz,effective_stage text,fingerprint text,archived boolean,channel_id text,origin_revision integer,private_client_archived boolean,service_label text,snoozed boolean,snooze_revision integer,created_day date) language plpgsql stable security invoker set search_path=public,pg_temp as $$declare today date:=pro_lead_inbox_today();begin
 perform pro_lead_origin_owner(p_actor);
 return query with raw as materialized(select s.*,false archived from pro_lead_commercial_sources(p_actor,false,p_query)s union all select s.*,true from pro_lead_commercial_sources(p_actor,true,p_query)s)
 select r.kind,r.id,r.created_at,r.effective_stage,r.fingerprint,r.archived,a.channel_id,coalesce(a.revision,0),
  case when r.kind='request' then exists(select 1 from pro_clients c join pro_appointment_requests x on x.owner_id=c.user_id and c.id='reservation-'||x.client_user_id::text where x.owner_id=p_actor and x.id=r.id and c.archived) else false end,
  case when r.kind='manual' then coalesce(nullif(btrim(l.project_type),''),btrim(l.title)) else btrim(q.service) end,
  coalesce(z.active and z.until_date>today,false),coalesce(z.revision,0),(r.created_at at time zone 'America/Costa_Rica')::date
 from raw r left join pro_lead_origin_assignments a on a.owner_id=p_actor and a.kind=r.kind and a.id=r.id
 left join pro_lead_center_records l on r.kind='manual' and l.owner_id=p_actor and l.kind='manual' and l.id=r.id
 left join pro_appointment_requests q on r.kind='request' and q.owner_id=p_actor and q.id=r.id
 left join pro_lead_snoozes z on z.owner_id=p_actor and z.kind=r.kind and z.id=r.id;end $$;
create or replace function public.pro_lead_inbox_read(p_actor uuid,p_box text default 'active',p_stage text default null,p_query text default '',p_service text default null,p_channel text default null,p_from date default null,p_to date default null,p_after text default null,p_snapshot text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare catalog jsonb;answer jsonb;actual_token text;cursor_valid boolean;service_key text:=lower(btrim(coalesce(p_service,'')));begin
 perform pro_lead_origin_owner(p_actor);catalog:=pro_lead_origin_stage_catalog(p_actor);
 if p_box is null or p_box not in('active','snoozed','archived') or p_query is null or length(p_query)>100 or length(coalesce(p_service,''))>160 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage) or p_after is not null and p_after!~'^(manual|request):[a-f0-9-]{36}$' or (p_after is null)<>(p_snapshot is null) or p_from is not null and p_from not between date'1900-01-01' and date'2100-12-31' or p_to is not null and p_to not between date'1900-01-01' and date'2100-12-31' or p_from>p_to then raise exception 'Invalid inbox query' using errcode='22023';end if;
 if p_channel is not null and p_channel<>'unspecified' and pro_lead_origin_channel_json(p_actor,p_channel) is null then raise exception 'Invalid attribution filter' using errcode='22023';end if;
 with base as materialized(select * from pro_lead_inbox_sources(p_actor,p_query)),
 filtered as materialized(select b.*,case when b.archived then 'archived' when b.snoozed then 'snoozed' else 'active' end box from base b where(service_key='' or lower(b.service_label)=service_key) and(p_channel is null or p_channel='unspecified' and b.channel_id is null or b.channel_id=p_channel) and(p_from is null or b.created_day>=p_from) and(p_to is null or b.created_day<=p_to)),
 sources as materialized(select * from filtered where box=p_box),
 metadata as(select md5(p_actor::text||p_box||coalesce(p_stage,'all')||p_query||service_key||coalesce(p_channel,'all')||coalesce(p_from::text,'')||coalesce(p_to::text,'')||pro_lead_inbox_today()::text||catalog::text||(select coalesce(jsonb_agg(to_jsonb(c) order by c.id)::text,'[]') from pro_lead_origin_catalog(p_actor)c)||coalesce(string_agg(jsonb_build_array(kind,id,created_at,effective_stage,fingerprint,channel_id,origin_revision,private_client_archived,snooze_revision)::text,',' order by created_at desc,kind,id desc),''))token from sources),
 anchor as(select * from sources where kind=split_part(p_after,':',1) and id=split_part(p_after,':',2)::uuid and(p_stage is null or effective_stage=p_stage)),
 selected as materialized(select * from sources where(p_stage is null or effective_stage=p_stage) and(p_after is null or created_at<(select created_at from anchor) or created_at=(select created_at from anchor) and(kind>(select kind from anchor) or kind=(select kind from anchor) and id<(select id from anchor))) order by created_at desc,kind,id desc limit 21),
 page as(select coalesce(jsonb_agg(pro_lead_origin_item(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)items,
  coalesce(jsonb_agg(pro_lead_commercial_progress(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)stages,
  coalesce(jsonb_agg(pro_lead_origin_get(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)context,
  coalesce(jsonb_agg(pro_lead_snooze_json(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)snoozes
  from(select * from selected order by created_at desc,kind,id desc limit 20)v),
 counts as(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from sources where effective_stage=s->>'id')) order by(s->>'position')::integer)items from jsonb_array_elements(catalog->'stages')s),
 inbox as(select jsonb_build_object('active',(select count(*) from filtered where box='active'),'snoozed',(select count(*) from filtered where box='snoozed'),'archived',(select count(*) from filtered where box='archived'),'imports',(select count(*) from pro_lead_imports where owner_id=p_actor),
  'stages',(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from filtered f where f.box='active' and f.effective_stage=s->>'id')) order by(s->>'position')::integer) from jsonb_array_elements(catalog->'stages')s))v),
 services as(select coalesce(jsonb_agg(label order by lower(label),label),'[]'::jsonb)v from(select min(service_label)label from base where service_label<>'' group by lower(service_label) order by lower(min(service_label)) limit 100)x)
 select jsonb_build_object('page',jsonb_build_object('catalog',catalog,'items',page.items,'counts',counts.items,'nextCursor',case when(select count(*) from selected)>20 then(select kind||':'||id::text from selected order by created_at desc,kind,id desc offset 19 limit 1)else null end,'snapshotToken',metadata.token),
  'stages',page.stages,'context',page.context,'snoozes',page.snoozes,'inboxes',inbox.v,'services',services.v),metadata.token,(p_after is null or exists(select 1 from anchor))
 into answer,actual_token,cursor_valid from page cross join counts cross join metadata cross join inbox cross join services;
 if p_after is not null and(p_snapshot is null or p_snapshot<>actual_token or not cursor_valid) then raise exception 'Leads changed; refresh before continuing' using errcode='40001';end if;return answer;end $$;

-- Funnel for one Costa Rica period. Conversion is only an explicit, still valid work link:
-- manual -> pro_manual_lead_works with its private work; request -> its non-cancelled work.
create or replace function public.pro_lead_inbox_funnel(p_actor uuid,p_from date,p_to date) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare catalog jsonb;answer jsonb;begin
 perform pro_lead_origin_owner(p_actor);catalog:=pro_lead_origin_stage_catalog(p_actor);
 if p_from is null or p_to is null or p_from not between date'1900-01-01' and date'2100-12-31' or p_to not between date'1900-01-01' and date'2100-12-31' or p_from>p_to or p_to-p_from>3660 then raise exception 'Invalid funnel period' using errcode='22023';end if;
 with base as materialized(select b.*,case when b.kind='manual' then exists(select 1 from pro_manual_lead_works m join pro_work w on w.user_id=m.owner_id and w.id=m.work_id_text and w."clientId"=m.source_client_id and w."bookingClientId" is null where m.owner_id=p_actor and m.lead_kind='manual' and m.lead_id=b.id)
   else exists(select 1 from pro_appointment_requests q join pro_work w on w.user_id=p_actor and w.id=q.work_id where q.owner_id=p_actor and q.id=b.id and not w.cancelled) end converted
  from pro_lead_inbox_sources(p_actor,'')b where b.created_day between p_from and p_to)
 select jsonb_build_object('from',to_char(p_from,'YYYY-MM-DD'),'to',to_char(p_to,'YYYY-MM-DD'),'catalog',catalog,'received',count(*),'manual',count(*) filter(where kind='manual'),'request',count(*) filter(where kind='request'),
  'open',count(*) filter(where not archived),'snoozed',count(*) filter(where not archived and snoozed),'archived',count(*) filter(where archived),'converted',count(*) filter(where converted),
  'conversionRate',case when count(*)=0 then null else round(count(*) filter(where converted)*100.0/count(*),1) end,
  'stages',(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from base x where not x.archived and x.effective_stage=s->>'id')) order by(s->>'position')::integer) from jsonb_array_elements(catalog->'stages')s))
 into answer from base;return answer;end $$;

create or replace function public.pro_lead_inbox_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception 'Immutable lead inbox history/receipt' using errcode='23514';end $$;
do $$declare t text;f record;begin
 foreach t in array array['pro_lead_snoozes','pro_lead_snooze_history','pro_lead_inbox_actions','pro_lead_imports','pro_lead_import_rows'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;
 foreach t in array array['pro_lead_snooze_history','pro_lead_inbox_actions','pro_lead_import_rows'] loop execute format('drop trigger if exists pro_lead_inbox_immutable on public.%I',t);execute format('create trigger pro_lead_inbox_immutable before update on public.%I for each row execute function pro_lead_inbox_immutable()',t);end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and(p.proname like 'pro_lead_inbox_%' or p.proname like 'pro_lead_snooze_%' or p.proname like 'pro_lead_import_%' or p.proname='pro_lead_imports_read') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';

-- ===== company-vendors-local.sql =====
-- LOCAL PRO ONLY. Company > Vendors directory (Houzz-style "Vendors" under Company).
-- Reuses the existing supplier table of Expenses (pro_expense_suppliers), which Purchase
-- orders already reference, and adds a 1:1 profile with kind (supplier/subcontractor),
-- trade, contact person and notes. Totals are read-only aggregates of existing purchase
-- orders and expenses. Nothing is sent, paid or published. Reapplicable.
begin;
create table if not exists public.pro_company_vendor_profiles(
 owner_id uuid not null,supplier_id uuid not null,
 kind text not null default 'supplier' check(kind in('supplier','subcontractor')),
 trade text check(trade is null or length(btrim(trade)) between 1 and 80),
 contact_name text check(contact_name is null or length(btrim(contact_name)) between 1 and 160),
 notes text check(notes is null or length(btrim(notes)) between 1 and 2000),
 revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,supplier_id),
 foreign key(owner_id,supplier_id) references public.pro_expense_suppliers(user_id,id) on delete cascade
);
-- Round 4B (2026-11-13): optional postal/physical address of the vendor (directory only).
alter table public.pro_company_vendor_profiles add column if not exists address text;
alter table public.pro_company_vendor_profiles drop constraint if exists pro_company_vendor_profiles_address_check;
alter table public.pro_company_vendor_profiles add constraint pro_company_vendor_profiles_address_check check(address is null or length(btrim(address)) between 1 and 300);
create table if not exists public.pro_company_vendor_history(
 owner_id uuid not null,supplier_id uuid not null,action_id uuid not null,
 action text not null check(action in('create','update','archive','restore')),
 before_value jsonb,after_value jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(owner_id,action_id),
 foreign key(owner_id,supplier_id) references public.pro_expense_suppliers(user_id,id) on delete cascade
);
create index if not exists pro_company_vendor_history_page on public.pro_company_vendor_history(owner_id,supplier_id,at desc);
create table if not exists public.pro_company_vendor_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id)
);
create index if not exists pro_expense_suppliers_name_page on public.pro_expense_suppliers(user_id,archived,lower(name),id);

-- Full vendor view: directory fields plus committed/paid totals from existing modules (CRC cents).
create or replace function public.pro_company_vendor_json(p_owner uuid,p_supplier uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',s.id,'name',s.name,'kind',coalesce(p.kind,'supplier'),'trade',p.trade,'contactName',p.contact_name,
  'address',p.address,'email',s.email,'phone',s.phone,'identification',s.identification,'notes',p.notes,'archived',s.archived,
  'revision',coalesce(p.revision,0),'updatedAt',p.updated_at,
  'purchaseOrders',jsonb_build_object('count',po.n,'committedCents',po.committed,'paidCents',pp.paid),
  'expenses',jsonb_build_object('count',ex.n,'amountCents',ex.amount,'paidCents',ep.paid))
 from public.pro_expense_suppliers s
 left join public.pro_company_vendor_profiles p on p.owner_id=s.user_id and p.supplier_id=s.id
 cross join lateral(select count(distinct o.id)::integer n,coalesce(sum(l.subtotal_cents+l.tax_cents),0)::bigint committed
  from public.pro_purchase_orders o left join public.pro_purchase_order_lines l on l.owner_id=o.owner_id and l.order_id=o.id
  where o.owner_id=s.user_id and o.supplier_id=s.id and o.status<>'cancelled') po
 cross join lateral(select coalesce(sum(case when y.kind='payment' then y.amount_cents else -y.amount_cents end),0)::bigint paid
  from public.pro_purchase_orders o join public.pro_purchase_order_payments y on y.owner_id=o.owner_id and y.order_id=o.id
  where o.owner_id=s.user_id and o.supplier_id=s.id) pp
 cross join lateral(select count(*)::integer n,coalesce(sum(e.amount_cents),0)::bigint amount
  from public.pro_internal_expenses e where e.user_id=s.user_id and e.supplier_id=s.id) ex
 cross join lateral(select coalesce(sum(case when y.kind='payment' then y.amount_cents else -y.amount_cents end),0)::bigint paid
  from public.pro_internal_expenses e join public.pro_expense_payments y on y.user_id=e.user_id and y.expense_id=e.id
  where e.user_id=s.user_id and e.supplier_id=s.id) ep
 where s.user_id=p_owner and s.id=p_supplier;
$$;

-- Directory-only snapshot for the immutable history (no totals).
create or replace function public.pro_company_vendor_snapshot(p_owner uuid,p_supplier uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('name',s.name,'kind',coalesce(p.kind,'supplier'),'trade',p.trade,'contactName',p.contact_name,'address',p.address,'email',s.email,
  'phone',s.phone,'identification',s.identification,'notes',p.notes,'archived',s.archived,'revision',coalesce(p.revision,0))
 from public.pro_expense_suppliers s left join public.pro_company_vendor_profiles p on p.owner_id=s.user_id and p.supplier_id=s.id
 where s.user_id=p_owner and s.id=p_supplier;
$$;

create or replace function public.pro_company_vendors_read(p_actor uuid,p_query jsonb) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v text;st text;knd text;q text;after_id uuid;after_name text;rows jsonb;next_id uuid;sid uuid;hist jsonb;receipt public.pro_company_vendor_actions;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_query) is distinct from 'object' then raise exception 'Invalid query' using errcode='22023';end if;
 v:=p_query->>'view';
 if v='list' then
  st:=coalesce(p_query->>'status','active');knd:=coalesce(p_query->>'kind','all');q:=lower(btrim(coalesce(p_query->>'q','')));
  if st not in('active','archived') or knd not in('all','supplier','subcontractor') or length(q)>100 then raise exception 'Invalid query' using errcode='22023';end if;
  if nullif(p_query->>'after','') is not null then
   after_id:=(p_query->>'after')::uuid;
   select lower(name) into after_name from public.pro_expense_suppliers where user_id=p_actor and id=after_id;
   if not found then raise exception 'Invalid cursor' using errcode='22023';end if;
  end if;
  select coalesce(jsonb_agg(public.pro_company_vendor_json(p_actor,x.id) order by x.k,x.id),'[]'::jsonb),
   (array_agg(x.id order by x.k desc,x.id desc))[1]
   into rows,next_id from(
   select s.id,lower(s.name) k from public.pro_expense_suppliers s
   left join public.pro_company_vendor_profiles p on p.owner_id=s.user_id and p.supplier_id=s.id
   where s.user_id=p_actor and s.archived=(st='archived') and (knd='all' or coalesce(p.kind,'supplier')=knd)
    and (q='' or strpos(lower(concat_ws(' ',s.name,s.identification,s.email,s.phone,p.contact_name,p.trade,p.address)),q)>0)
    and (after_id is null or (lower(s.name),s.id)>(after_name,after_id))
   order by lower(s.name),s.id limit 20) x;
  -- One extra probe decides whether a next page exists without returning it.
  if next_id is not null and not exists(select 1 from public.pro_expense_suppliers s
   left join public.pro_company_vendor_profiles p on p.owner_id=s.user_id and p.supplier_id=s.id
   where s.user_id=p_actor and s.archived=(st='archived') and (knd='all' or coalesce(p.kind,'supplier')=knd)
    and (q='' or strpos(lower(concat_ws(' ',s.name,s.identification,s.email,s.phone,p.contact_name,p.trade,p.address)),q)>0)
    and (lower(s.name),s.id)>((select lower(name) from public.pro_expense_suppliers where user_id=p_actor and id=next_id),next_id)) then next_id:=null;end if;
  return jsonb_build_object('items',rows,'nextCursor',next_id,'counts',(select jsonb_build_object('active',count(*) filter(where not archived),'archived',count(*) filter(where archived)) from public.pro_expense_suppliers where user_id=p_actor));
 elsif v='detail' then
  sid:=(p_query->>'id')::uuid;
  if not exists(select 1 from public.pro_expense_suppliers where user_id=p_actor and id=sid) then return null;end if;
  select coalesce(jsonb_agg(jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_value,'after',h.after_value) order by h.at desc),'[]'::jsonb) into hist
   from(select * from public.pro_company_vendor_history where owner_id=p_actor and supplier_id=sid order by at desc limit 20) h;
  return jsonb_build_object('vendor',public.pro_company_vendor_json(p_actor,sid),'history',hist);
 elsif v='action' then
  select * into receipt from public.pro_company_vendor_actions where owner_id=p_actor and action_id=(p_query->>'actionId')::uuid;
  return jsonb_build_object('receipt',case when found then jsonb_build_object('input',receipt.input,'result',receipt.result) end);
 end if;
 raise exception 'Invalid query' using errcode='22023';
end $$;

create or replace function public.pro_company_vendors_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;sid uuid;rev integer;keys text[];expected text[];receipt public.pro_company_vendor_actions;
 supplier public.pro_expense_suppliers;profile public.pro_company_vendor_profiles;before_json jsonb;after_json jsonb;result jsonb;
 v_name text;v_kind text;v_trade text;v_contact text;v_email text;v_phone text;v_ident text;v_notes text;v_address text;has_address boolean;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid vendor' using errcode='22023';end if;
 act:=p_input->>'action';
 -- 'address' is optional (Round 4B): an older client without it keeps the saved address.
 has_address:=p_input ? 'address';
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input-'address') key;
 expected:=case act
  when 'create' then array['action','actionId','contactName','email','id','identification','kind','name','notes','phone','trade']
  when 'update' then array['action','actionId','contactName','email','id','identification','kind','name','notes','phone','revision','trade']
  when 'archive' then array['action','actionId','id','revision']
  when 'restore' then array['action','actionId','id','revision'] end;
 if expected is null or keys is distinct from expected or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'id') is distinct from 'string'
  or (act<>'create' and (jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,9}$',false))) then
  raise exception 'Invalid vendor fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;sid:=(p_input->>'id')::uuid;rev:=case when act='create' then 0 else (p_input->>'revision')::integer end;
 if act in('create','update') then
  if jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'kind') is distinct from 'string'
   or jsonb_typeof(p_input->'email') is distinct from 'string' or jsonb_typeof(p_input->'phone') is distinct from 'string' or jsonb_typeof(p_input->'identification') is distinct from 'string'
   or jsonb_typeof(p_input->'trade') not in('string','null') or jsonb_typeof(p_input->'contactName') not in('string','null') or jsonb_typeof(p_input->'notes') not in('string','null')
   or has_address and jsonb_typeof(p_input->'address') not in('string','null') then
   raise exception 'Invalid vendor fields' using errcode='22023';end if;
  v_name:=btrim(p_input->>'name');v_kind:=p_input->>'kind';v_email:=btrim(p_input->>'email');v_phone:=btrim(p_input->>'phone');v_ident:=btrim(p_input->>'identification');
  v_trade:=nullif(btrim(coalesce(p_input->>'trade','')),'');v_contact:=nullif(btrim(coalesce(p_input->>'contactName','')),'');v_notes:=nullif(btrim(coalesce(p_input->>'notes','')),'');v_address:=nullif(btrim(coalesce(p_input->>'address','')),'');
  if length(v_name) not between 1 and 160 or v_kind not in('supplier','subcontractor') or length(v_email)>254 or length(v_phone)>40 or length(v_ident)>40
   or length(v_trade)>80 or length(v_contact)>160 or length(v_notes)>2000 or length(v_address)>300 or (v_email<>'' and v_email!~'^[^@\s]+@[^@\s]+\.[^@\s]+$') then
   raise exception 'Invalid vendor values' using errcode='22023';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-vendor-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_company_vendor_actions where owner_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 -- Same serialization point and revision counter as Expenses, so its open forms see the change.
 insert into public.pro_expense_state(user_id) values(p_actor) on conflict do nothing;
 perform 1 from public.pro_expense_state where user_id=p_actor for update;
 perform set_config('pro.company_vendor_write','1',true);
 -- No key change: purchase orders and expenses keep taking their FK key-share lock without waiting.
 select * into supplier from public.pro_expense_suppliers where user_id=p_actor and id=sid for no key update;
 if act='create' then
  if found then raise exception 'Vendor id already used' using errcode='23505';end if;
  if (select count(*) from public.pro_expense_suppliers where user_id=p_actor)>=2000 then raise exception 'Vendor limit' using errcode='23514';end if;
  insert into public.pro_expense_suppliers(user_id,id,name,identification,email,phone,archived) values(p_actor,sid,v_name,v_ident,v_email,v_phone,false);
  insert into public.pro_company_vendor_profiles(owner_id,supplier_id,kind,trade,contact_name,notes,address) values(p_actor,sid,v_kind,v_trade,v_contact,v_notes,v_address);
  before_json:=null;
 else
  if not found then raise exception 'Vendor not found' using errcode='P0002';end if;
  select * into profile from public.pro_company_vendor_profiles where owner_id=p_actor and supplier_id=sid for update;
  if coalesce(profile.revision,0)<>rev then raise exception 'Vendor changed' using errcode='40001';end if;
  before_json:=public.pro_company_vendor_snapshot(p_actor,sid);
  if act='update' then
   if not has_address then v_address:=profile.address;end if;
   if supplier.name=v_name and supplier.email=v_email and supplier.phone=v_phone and supplier.identification=v_ident
    and coalesce(profile.kind,'supplier')=v_kind and profile.trade is not distinct from v_trade and profile.contact_name is not distinct from v_contact and profile.notes is not distinct from v_notes and profile.address is not distinct from v_address then
    raise exception 'No vendor changes' using errcode='22023';end if;
   update public.pro_expense_suppliers set name=v_name,email=v_email,phone=v_phone,identification=v_ident where user_id=p_actor and id=sid;
  else
   if supplier.archived=(act='archive') then raise exception 'Vendor already in that state' using errcode='22023';end if;
   update public.pro_expense_suppliers set archived=(act='archive') where user_id=p_actor and id=sid;
  end if;
  if profile.supplier_id is null then
   insert into public.pro_company_vendor_profiles(owner_id,supplier_id,kind,trade,contact_name,notes,address)
    values(p_actor,sid,coalesce(v_kind,'supplier'),v_trade,v_contact,v_notes,v_address);
  else
   update public.pro_company_vendor_profiles set kind=coalesce(v_kind,kind),trade=case when act='update' then v_trade else trade end,
    contact_name=case when act='update' then v_contact else contact_name end,notes=case when act='update' then v_notes else notes end,address=case when act='update' then v_address else address end,
    revision=revision+1,updated_at=now() where owner_id=p_actor and supplier_id=sid;
  end if;
 end if;
 perform set_config('pro.company_vendor_write','',true);
 update public.pro_expense_state set revision=revision+1 where user_id=p_actor;
 after_json:=public.pro_company_vendor_snapshot(p_actor,sid);
 result:=jsonb_build_object('vendor',public.pro_company_vendor_json(p_actor,sid));
 insert into public.pro_company_vendor_history(owner_id,supplier_id,action_id,action,before_value,after_value) values(p_actor,sid,aid,act,before_json,after_json);
 insert into public.pro_company_vendor_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- When Expenses edits a supplier directly, the directory revision moves too, so a stale
-- directory form receives 409 instead of overwriting that change.
create or replace function public.pro_company_vendor_supplier_touch() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if coalesce(current_setting('pro.company_vendor_write',true),'')='1' then return new;end if;
 if (old.name,old.identification,old.email,old.phone,old.archived) is not distinct from (new.name,new.identification,new.email,new.phone,new.archived) then return new;end if;
 insert into public.pro_company_vendor_profiles(owner_id,supplier_id) values(new.user_id,new.id)
  on conflict(owner_id,supplier_id) do update set revision=public.pro_company_vendor_profiles.revision+1,updated_at=now();
 return new;
end $$;
drop trigger if exists pro_company_vendor_supplier_touch on public.pro_expense_suppliers;
create trigger pro_company_vendor_supplier_touch after update on public.pro_expense_suppliers for each row execute function public.pro_company_vendor_supplier_touch();

create or replace function public.pro_company_vendor_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Vendor history and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_company_vendor_history_immutable on public.pro_company_vendor_history;
create trigger pro_company_vendor_history_immutable before update on public.pro_company_vendor_history for each row execute function public.pro_company_vendor_immutable();
drop trigger if exists pro_company_vendor_action_immutable on public.pro_company_vendor_actions;
create trigger pro_company_vendor_action_immutable before update on public.pro_company_vendor_actions for each row execute function public.pro_company_vendor_immutable();

alter table public.pro_company_vendor_profiles enable row level security;
alter table public.pro_company_vendor_history enable row level security;
alter table public.pro_company_vendor_actions enable row level security;
revoke all on public.pro_company_vendor_profiles,public.pro_company_vendor_history,public.pro_company_vendor_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_company_vendor_profiles,public.pro_company_vendor_history,public.pro_company_vendor_actions to service_role;
revoke all on function public.pro_company_vendor_json(uuid,uuid),public.pro_company_vendor_snapshot(uuid,uuid),public.pro_company_vendors_read(uuid,jsonb),public.pro_company_vendors_mutate(uuid,jsonb),public.pro_company_vendor_supplier_touch(),public.pro_company_vendor_immutable() from public,anon,authenticated;
grant execute on function public.pro_company_vendor_json(uuid,uuid),public.pro_company_vendor_snapshot(uuid,uuid),public.pro_company_vendors_read(uuid,jsonb),public.pro_company_vendors_mutate(uuid,jsonb) to service_role;
commit;

-- ===== takeoffs-local.sql =====
-- LOCAL PRO ONLY. Mediciones sobre planos (row 66 of the parity register).
-- Per job (pro_work): plans → pages → measurements (area, length, count).
-- Plan images reuse the existing private job files (pro_work_files, bucket
-- pro-work-files): no new bucket. Only JPEG files (the work-files upload
-- normalizes JPEG/PNG/WebP to JPEG) can be a plan; PDF stays pending until a
-- PDF renderer is available (see docs/pro/takeoffs-local.md).
-- Geometry is stored as integer millionths of the page (0..1000000 for 0..1)
-- plus the page size in pixels. Results are computed here, in numeric, and
-- returned as integer thousandths (milli-units). No floats are stored.
-- "Send to estimate" writes lines through the existing private estimate writer
-- (pro_private_estimate_mutate); nothing here publishes, charges, invoices or
-- notifies anyone. The customer view never reads these tables.
begin;
create table if not exists public.pro_work_takeoff_plans(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,work_id text not null,
 file_id uuid not null,position bigint generated always as identity,
 title text not null check(title=btrim(title) and length(title) between 1 and 160),
 page_count integer not null default 1 check(page_count between 1 and 200),
 archived boolean not null default false,
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,work_id,id),unique(owner_id,file_id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 -- Reuses the private job files: only a file of this same job can be a plan.
 foreign key(owner_id,work_id,file_id) references public.pro_work_files(owner_id,work_id,id) on delete cascade
);
create unique index if not exists pro_work_takeoff_plan_global_id on public.pro_work_takeoff_plans(id);
create index if not exists pro_work_takeoff_plan_page on public.pro_work_takeoff_plans(owner_id,work_id,position);
create table if not exists public.pro_work_takeoff_pages(
 owner_id uuid not null,plan_id uuid not null,page_number integer not null check(page_number between 1 and 200),
 width_px integer not null check(width_px between 1 and 20000),height_px integer not null check(height_px between 1 and 20000),
 unit text not null default 'm' check(unit in('m','ft')),
 cal_x1 integer check(cal_x1 between 0 and 1000000),cal_y1 integer check(cal_y1 between 0 and 1000000),
 cal_x2 integer check(cal_x2 between 0 and 1000000),cal_y2 integer check(cal_y2 between 0 and 1000000),
 cal_length_milli bigint check(cal_length_milli between 1 and 1000000),
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default now(),
 primary key(owner_id,plan_id,page_number),
 foreign key(owner_id,plan_id) references public.pro_work_takeoff_plans(owner_id,id) on delete cascade,
 check((cal_x1 is null and cal_y1 is null and cal_x2 is null and cal_y2 is null and cal_length_milli is null)
  or (cal_x1 is not null and cal_y1 is not null and cal_x2 is not null and cal_y2 is not null and cal_length_milli is not null))
);
create table if not exists public.pro_work_takeoff_measurements(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,work_id text not null,
 plan_id uuid not null,page_number integer not null,position bigint generated always as identity,
 kind text not null check(kind in('area','length','count')),
 name text not null check(name=btrim(name) and length(name) between 1 and 120),
 category_id uuid,color text not null check(color~'^#[0-9a-f]{6}$'),hidden boolean not null default false,
 points jsonb not null default '[]'::jsonb check(jsonb_typeof(points)='array' and jsonb_array_length(points)<=400),
 manual_milli bigint check(manual_milli between 1 and 1000000000000),
 multiplier_mode text not null default 'none' check(multiplier_mode in('none','height','factor')),
 multiplier_milli bigint check(multiplier_milli between 1 and 100000000),
 waste_bps integer not null default 0 check(waste_bps between 0 and 10000),
 product_id text,archived boolean not null default false,
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 foreign key(owner_id,work_id,plan_id) references public.pro_work_takeoff_plans(owner_id,work_id,id) on delete cascade,
 foreign key(owner_id,plan_id,page_number) references public.pro_work_takeoff_pages(owner_id,plan_id,page_number) on delete cascade,
 check((multiplier_mode='none')=(multiplier_milli is null)),
 check(multiplier_mode<>'height' or kind='length'),
 -- Either drawn points or a value typed without a pointer, never both.
 check((manual_milli is null)=(jsonb_array_length(points)>0))
);
create unique index if not exists pro_work_takeoff_measurement_global_id on public.pro_work_takeoff_measurements(id);
create index if not exists pro_work_takeoff_measurement_page on public.pro_work_takeoff_measurements(owner_id,work_id,position);
create table if not exists public.pro_work_takeoff_history(
 owner_id uuid not null,work_id text not null,action_id uuid not null,actor_id uuid not null,
 action text not null check(action in('plan_create','plan_update','plan_archive','plan_restore','page_calibrate','measurement_create','measurement_update','measurement_visibility','measurement_archive','measurement_restore','send_estimate')),
 target_kind text not null check(target_kind in('plan','page','measurement','estimate')),target_id text not null,
 before_value jsonb,after_value jsonb not null,at timestamptz not null default now(),
 primary key(owner_id,action_id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_work_takeoff_history_page on public.pro_work_takeoff_history(owner_id,work_id,at desc);
create table if not exists public.pro_work_takeoff_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id)
);

-- Deterministic id with the RFC 4122 version-4 layout (accepted by strict uuid validators).
create or replace function public.pro_work_takeoff_uuid(p_seed text) returns uuid
language sql immutable security invoker set search_path=public,pg_temp as $$
 select (substr(h,1,8)||'-'||substr(h,9,4)||'-4'||substr(h,14,3)||'-8'||substr(h,18,3)||'-'||substr(h,21,12))::uuid from (select md5(p_seed) h) x;
$$;
-- Normalized point list: [[x,y],...] with 0<=x,y<=1 and at most 6 decimals → integer millionths.
create or replace function public.pro_work_takeoff_points(p_value jsonb,p_min integer,p_max integer) returns jsonb
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare p jsonb;x numeric;y numeric;out_points jsonb:='[]'::jsonb;
begin
 if jsonb_typeof(p_value) is distinct from 'array' or jsonb_array_length(p_value) not between p_min and p_max then raise exception 'Invalid points' using errcode='22023';end if;
 for p in select value from jsonb_array_elements(p_value) loop
  if jsonb_typeof(p) is distinct from 'array' or jsonb_array_length(p)<>2 or jsonb_typeof(p->0) is distinct from 'number' or jsonb_typeof(p->1) is distinct from 'number' then raise exception 'Invalid point' using errcode='22023';end if;
  x:=(p->>0)::numeric;y:=(p->>1)::numeric;
  if x not between 0 and 1 or y not between 0 and 1 or x*1000000<>round(x*1000000) or y*1000000<>round(y*1000000) then raise exception 'Invalid point' using errcode='22023';end if;
  out_points:=out_points||jsonb_build_array(jsonb_build_array((x*1000000)::integer,(y*1000000)::integer));
 end loop;
 return out_points;
end $$;
-- Pixel distance between two stored points of a page of width×height pixels.
create or replace function public.pro_work_takeoff_px_distance(p_x1 integer,p_y1 integer,p_x2 integer,p_y2 integer,p_w integer,p_h integer) returns numeric
language sql immutable security invoker set search_path=public,pg_temp as $$
 select sqrt(power((p_x2-p_x1)::numeric*p_w/1000000,2)+power((p_y2-p_y1)::numeric*p_h/1000000,2));
$$;
-- Sum of segment lengths (open polyline) in pixels.
create or replace function public.pro_work_takeoff_px_length(p_points jsonb,p_w integer,p_h integer) returns numeric
language sql immutable security invoker set search_path=public,pg_temp as $$
 select coalesce(sum(public.pro_work_takeoff_px_distance(a.x,a.y,a.nx,a.ny,p_w,p_h)),0) from (
  select (e.value->>0)::integer x,(e.value->>1)::integer y,
   lead((e.value->>0)::integer) over(order by e.ord) nx,lead((e.value->>1)::integer) over(order by e.ord) ny
  from jsonb_array_elements(p_points) with ordinality e(value,ord)
 ) a where a.nx is not null;
$$;
-- Polygon area in square pixels (shoelace formula, closed automatically).
create or replace function public.pro_work_takeoff_px_area(p_points jsonb,p_w integer,p_h integer) returns numeric
language sql immutable security invoker set search_path=public,pg_temp as $$
 select abs(coalesce(sum(a.x::numeric*a.ny-a.nx::numeric*a.y),0))/2*p_w*p_h/1000000000000 from (
  select (e.value->>0)::integer x,(e.value->>1)::integer y,
   coalesce(lead((e.value->>0)::integer) over(order by e.ord),first_value((e.value->>0)::integer) over(order by e.ord)) nx,
   coalesce(lead((e.value->>1)::integer) over(order by e.ord),first_value((e.value->>1)::integer) over(order by e.ord)) ny
  from jsonb_array_elements(p_points) with ordinality e(value,ord)
 ) a;
$$;
-- Result of one measurement on its page, in thousandths of the unit.
-- unit: m, m2, ft, ft2 or u (units). A drawn area/length needs a calibrated page.
create or replace function public.pro_work_takeoff_result(p_row public.pro_work_takeoff_measurements,p_page public.pro_work_takeoff_pages) returns jsonb
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare base numeric;total numeric;cal numeric;base_unit text;total_unit text;
begin
 base_unit:=case p_row.kind when 'count' then 'u' when 'area' then p_page.unit||'2' else p_page.unit end;
 total_unit:=case when p_row.multiplier_mode='height' then p_page.unit||'2' else base_unit end;
 if p_row.kind='count' then base:=coalesce(p_row.manual_milli,jsonb_array_length(p_row.points)*1000);
 elsif p_row.manual_milli is not null then base:=p_row.manual_milli;
 elsif p_page.cal_length_milli is null then
  return jsonb_build_object('baseMilli',null,'totalMilli',null,'baseUnit',base_unit,'unit',total_unit,'needsScale',true);
 else
  cal:=public.pro_work_takeoff_px_distance(p_page.cal_x1,p_page.cal_y1,p_page.cal_x2,p_page.cal_y2,p_page.width_px,p_page.height_px);
  if p_row.kind='length' then base:=round(public.pro_work_takeoff_px_length(p_row.points,p_page.width_px,p_page.height_px)*p_page.cal_length_milli/cal);
  else base:=round(public.pro_work_takeoff_px_area(p_row.points,p_page.width_px,p_page.height_px)*p_page.cal_length_milli*p_page.cal_length_milli/(cal*cal*1000));end if;
 end if;
 total:=base;
 if p_row.multiplier_mode<>'none' then total:=round(total*p_row.multiplier_milli/1000);end if;
 if p_row.waste_bps>0 then total:=round(total*(10000+p_row.waste_bps)/10000);end if;
 return jsonb_build_object('baseMilli',base,'totalMilli',total,'baseUnit',base_unit,'unit',total_unit,'needsScale',false);
end $$;
create or replace function public.pro_work_takeoff_norm(p_points jsonb) returns jsonb
language sql immutable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_array(round((e.value->>0)::numeric/1000000,6),round((e.value->>1)::numeric/1000000,6)) order by e.ord),'[]'::jsonb)
 from jsonb_array_elements(p_points) with ordinality e(value,ord);
$$;
create or replace function public.pro_work_takeoff_page_json(p_page public.pro_work_takeoff_pages) returns jsonb
language sql immutable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('pageNumber',p_page.page_number,'widthPx',p_page.width_px,'heightPx',p_page.height_px,'unit',p_page.unit,
  'calibration',case when p_page.cal_length_milli is null then null else jsonb_build_object(
   'points',public.pro_work_takeoff_norm(jsonb_build_array(jsonb_build_array(p_page.cal_x1,p_page.cal_y1),jsonb_build_array(p_page.cal_x2,p_page.cal_y2))),
   'lengthMilli',p_page.cal_length_milli) end,
  'revision',p_page.revision,'updatedAt',p_page.updated_at);
$$;
create or replace function public.pro_work_takeoff_plan_json(p_row public.pro_work_takeoff_plans) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'workId',p_row.work_id,'fileId',p_row.file_id,'position',p_row.position,'title',p_row.title,'pageCount',p_row.page_count,
  'fileName',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,
  'uploadedOn',to_char(p_row.created_at at time zone 'America/Costa_Rica','YYYY-MM-DD'),
  'pages',coalesce((select jsonb_agg(public.pro_work_takeoff_page_json(g) order by g.page_number) from public.pro_work_takeoff_pages g where g.owner_id=p_row.owner_id and g.plan_id=p_row.id),'[]'::jsonb),
  'archived',p_row.archived,'revision',p_row.revision,'createdAt',p_row.created_at,'updatedAt',p_row.updated_at)
 from public.pro_work_files f where f.owner_id=p_row.owner_id and f.work_id=p_row.work_id and f.id=p_row.file_id;
$$;
create or replace function public.pro_work_takeoff_measurement_json(p_row public.pro_work_takeoff_measurements) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'workId',p_row.work_id,'planId',p_row.plan_id,'pageNumber',p_row.page_number,'position',p_row.position,
  'kind',p_row.kind,'name',p_row.name,'categoryId',p_row.category_id,
  'categoryName',(select c.name from public.pro_catalog_organizations c where c.user_id=p_row.owner_id and c.kind='product_category' and c.id=p_row.category_id),
  'color',p_row.color,'hidden',p_row.hidden,'points',public.pro_work_takeoff_norm(p_row.points),'manualMilli',p_row.manual_milli,
  'multiplierMode',p_row.multiplier_mode,'multiplierMilli',p_row.multiplier_milli,'wasteBps',p_row.waste_bps,
  'productId',p_row.product_id,'productName',(select p.name from public.pro_products p where p.user_id=p_row.owner_id and p.id=p_row.product_id),
  'result',public.pro_work_takeoff_result(p_row,g),
  'archived',p_row.archived,'revision',p_row.revision,'createdAt',p_row.created_at,'updatedAt',p_row.updated_at)
 from public.pro_work_takeoff_pages g where g.owner_id=p_row.owner_id and g.plan_id=p_row.plan_id and g.page_number=p_row.page_number;
$$;
-- Project estimates that can receive measurement lines: linked to this job and never shared.
create or replace function public.pro_work_takeoff_estimates(p_actor uuid,p_work public.pro_work) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'title',d.title,'currency',d.currency,'revision',d.revision,'totalCents',d.total_cents,
  'lineCount',(select count(*) from public.pro_private_estimate_items i where i.owner_id=d.owner_id and i.estimate_id=d.id)) order by d.created_at desc,d.id desc),'[]'::jsonb)
 from public.pro_project_estimate_rows(p_actor,p_work) r join public.pro_private_estimates d on d.owner_id=p_actor and d.id=r.estimate_id
 where r.relation='project' and not d.archived and not exists(select 1 from public.pro_private_estimate_publications v where v.owner_id=p_actor and v.estimate_id=d.id);
$$;
create or replace function public.pro_work_takeoffs_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w public.pro_work;plans jsonb;measurements jsonb;categories jsonb;hist jsonb;can_quote boolean;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid takeoff query' using errcode='22023';end if;
 select * into w from public.pro_work where user_id=p_actor and id=p_work;
 if not found then return null;end if;
 select coalesce(jsonb_agg(public.pro_work_takeoff_plan_json(p) order by p.archived,p.position),'[]'::jsonb) into plans from public.pro_work_takeoff_plans p where p.owner_id=p_actor and p.work_id=p_work;
 select coalesce(jsonb_agg(public.pro_work_takeoff_measurement_json(m) order by m.archived,m.position),'[]'::jsonb) into measurements from public.pro_work_takeoff_measurements m where m.owner_id=p_actor and m.work_id=p_work;
 -- Company › Categories (product and service categories) are the reusable groups.
 select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'archived',c.archived) order by c.position),'[]'::jsonb) into categories
  from public.pro_catalog_organizations c where c.user_id=p_actor and c.kind='product_category'
  and (not c.archived or exists(select 1 from public.pro_work_takeoff_measurements m where m.owner_id=p_actor and m.work_id=p_work and m.category_id=c.id));
 select coalesce(jsonb_agg(x.content order by x.at desc,x.action_id),'[]'::jsonb) into hist from (
  select h.at,h.action_id,jsonb_build_object('actionId',h.action_id,'action',h.action,'targetKind',h.target_kind,'targetId',h.target_id,'at',h.at) as content
  from public.pro_work_takeoff_history h where h.owner_id=p_actor and h.work_id=p_work order by h.at desc,h.action_id limit 100
 ) x;
 can_quote:=not coalesce(w.cancelled,false) and exists(select 1 from public.pro_clients c where c.user_id=p_actor and c.id=w."clientId" and not coalesce(c.archived,false));
 return jsonb_build_object('workId',p_work,'today',to_char(now() at time zone 'America/Costa_Rica','YYYY-MM-DD'),'canQuote',can_quote,
  'plans',plans,'measurements',measurements,'categories',categories,'estimates',public.pro_work_takeoff_estimates(p_actor,w),'history',hist);
end $$;
-- Storage metadata of a ready job file of this owner (used to read the image size before creating a plan).
create or replace function public.pro_work_takeoff_file(p_actor uuid,p_work text,p_file uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare f public.pro_work_files;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or p_file is null then raise exception 'Invalid file' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into f from public.pro_work_files where owner_id=p_actor and work_id=p_work and id=p_file and ready;
 if not found then return null;end if;
 return jsonb_build_object('objectPath',f.object_path,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'sha256',f.sha256);
end $$;
-- Plan image for the owner only (the customer never sees takeoffs).
create or replace function public.pro_work_takeoff_image(p_actor uuid,p_plan uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare p public.pro_work_takeoff_plans;f public.pro_work_files;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into p from public.pro_work_takeoff_plans where owner_id=p_actor and id=p_plan;
 if not found then return null;end if;
 select * into f from public.pro_work_files where owner_id=p_actor and work_id=p.work_id and id=p.file_id and ready and mime_type='image/jpeg';
 if not found then return null;end if;
 return jsonb_build_object('objectPath',f.object_path,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'sha256',f.sha256);
end $$;
create or replace function public.pro_work_takeoff_text(p_value jsonb,p_max integer) returns text
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare v text;
begin
 if jsonb_typeof(p_value) is distinct from 'string' then raise exception 'Invalid takeoff text' using errcode='22023';end if;
 v:=nullif(btrim(p_value#>>'{}'),'');
 if v is null or length(v)>p_max then raise exception 'Invalid takeoff text' using errcode='22023';end if;
 return v;
end $$;
create or replace function public.pro_work_takeoff_int(p_value jsonb,p_min numeric,p_max numeric) returns bigint
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
begin
 if jsonb_typeof(p_value) is distinct from 'number' or not coalesce((p_value#>>'{}')~'^[0-9]{1,15}$',false) or (p_value#>>'{}')::numeric not between p_min and p_max then raise exception 'Invalid takeoff number' using errcode='22023';end if;
 return (p_value#>>'{}')::bigint;
end $$;
-- Lines written into the private estimate: the measurement total as quantity (milli),
-- its unit, and the price of the linked item of My items (or the price already typed).
create or replace function public.pro_work_takeoff_line(p_actor uuid,p_estimate uuid,p_row public.pro_work_takeoff_measurements,p_old jsonb,p_en boolean) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_work_takeoff_pages;r jsonb;qty numeric;unit_label text;product public.pro_products;price bigint;cat text;line_id uuid;
begin
 select * into g from public.pro_work_takeoff_pages where owner_id=p_actor and plan_id=p_row.plan_id and page_number=p_row.page_number;
 r:=public.pro_work_takeoff_result(p_row,g);
 if (r->>'needsScale')::boolean then raise exception 'Calibrate the page before quoting' using errcode='22023';end if;
 qty:=(r->>'totalMilli')::numeric;
 if qty not between 1 and 100000000 then raise exception 'Quantity outside the estimate range' using errcode='22023';end if;
 unit_label:=case r->>'unit' when 'm2' then 'm²' when 'ft2' then 'ft²' when 'm' then 'm' when 'ft' then 'ft' else case when p_en then 'ea' else 'unid.' end end;
 select name into cat from public.pro_catalog_organizations where user_id=p_actor and kind='product_category' and id=p_row.category_id;
 line_id:=public.pro_work_takeoff_uuid('pro-work-takeoff-line:'||p_estimate::text||':'||p_row.id::text);
 price:=coalesce((p_old->>'unitPriceCents')::bigint,0);
 if p_row.product_id is not null then
  select * into product from public.pro_products where user_id=p_actor and id=p_row.product_id;
  -- A new link (or a line never sent) takes the item price; a price already edited in the estimate is kept.
  if found and not product.archived and (p_old is null or p_old->>'catalogProductId' is distinct from p_row.product_id) then
   price:=round(product.price*100);
   if price not between 0 and 10000000000 then raise exception 'Item price outside the estimate range' using errcode='22023';end if;
  end if;
 end if;
 return jsonb_build_object('id',line_id,'description',left(case when cat is null then p_row.name else cat||' · '||p_row.name end,2000),'unit',unit_label,
  'qtyMilli',qty::bigint,'unitPriceCents',price,'discountBps',coalesce((p_old->>'discountBps')::bigint,0),'taxBps',coalesce((p_old->>'taxBps')::bigint,0),
  'catalogProductId',case when p_row.product_id is not null and exists(select 1 from public.pro_products where user_id=p_actor and id=p_row.product_id and not archived) then to_jsonb(p_row.product_id) else coalesce(p_old->'catalogProductId','null'::jsonb) end);
end $$;
create or replace function public.pro_work_takeoffs_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;wid text;aid uuid;tid uuid;rev integer;keys text[];expected text[];receipt public.pro_work_takeoff_actions;sendable boolean;
 plan public.pro_work_takeoff_plans;pg public.pro_work_takeoff_pages;m public.pro_work_takeoff_measurements;w public.pro_work;
 before_json jsonb;after_json jsonb;result jsonb;tkind text;target text;
 v_title text;v_name text;v_kind text;v_points jsonb;v_manual bigint;v_mode text;v_mult bigint;v_waste integer;v_color text;v_cat uuid;v_product text;v_plan uuid;v_page integer;
 v_unit text;v_cal jsonb;v_len bigint;v_w integer;v_h integer;v_file uuid;
 ids uuid[];mid uuid;est public.pro_private_estimates;eid uuid;ctx jsonb;issuer jsonb;lines jsonb;old_line jsonb;new_line jsonb;line_ids jsonb:='[]'::jsonb;estimate_input jsonb;answer jsonb;created boolean;en boolean;idx integer;
 measurement_fields text[]:=array['categoryId','color','manualMilli','multiplierMilli','multiplierMode','name','points','productId','wasteBps'];
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid takeoff' using errcode='22023';end if;
 act:=p_input->>'action';
 expected:=case act
  when 'plan_create' then array['action','actionId','fileId','heightPx','id','title','widthPx','workId']
  when 'plan_update' then array['action','actionId','id','revision','title','workId']
  when 'plan_archive' then array['action','actionId','id','revision','workId'] when 'plan_restore' then array['action','actionId','id','revision','workId']
  when 'page_calibrate' then array['action','actionId','calibration','id','pageNumber','revision','unit','workId']
  when 'measurement_create' then (select array_agg(k order by k) from unnest(measurement_fields||array['action','actionId','id','kind','pageNumber','planId','workId']) k)
  when 'measurement_update' then (select array_agg(k order by k) from unnest(measurement_fields||array['action','actionId','id','revision','workId']) k)
  when 'measurement_visibility' then array['action','actionId','hidden','id','revision','workId']
  when 'measurement_archive' then array['action','actionId','id','revision','workId'] when 'measurement_restore' then array['action','actionId','id','revision','workId']
  when 'send_estimate' then array['action','actionId','estimateId','estimateRevision','language','measurementIds','workId'] end;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if expected is null or keys is distinct from expected or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
  or act<>'send_estimate' and jsonb_typeof(p_input->'id') is distinct from 'string' then raise exception 'Invalid takeoff fields' using errcode='22023';end if;
 wid:=p_input->>'workId';aid:=(p_input->>'actionId')::uuid;
 if length(wid) not between 1 and 160 then raise exception 'Invalid takeoff identity' using errcode='22023';end if;
 if act<>'send_estimate' then tid:=(p_input->>'id')::uuid;end if;
 if p_input?'revision' then rev:=public.pro_work_takeoff_int(p_input->'revision',1,2147483646)::integer;end if;
 tkind:=case when act like 'plan_%' then 'plan' when act='page_calibrate' then 'page' when act='send_estimate' then 'estimate' else 'measurement' end;
 -- Field validation before any lock.
 if act in('plan_create','plan_update') then
  v_title:=public.pro_work_takeoff_text(p_input->'title',160);
  if act='plan_create' then
   if jsonb_typeof(p_input->'fileId') is distinct from 'string' then raise exception 'Invalid file' using errcode='22023';end if;
   v_file:=(p_input->>'fileId')::uuid;v_w:=public.pro_work_takeoff_int(p_input->'widthPx',1,20000);v_h:=public.pro_work_takeoff_int(p_input->'heightPx',1,20000);
  end if;
 elsif act='page_calibrate' then
  v_page:=public.pro_work_takeoff_int(p_input->'pageNumber',1,200);
  if jsonb_typeof(p_input->'unit') is distinct from 'string' or p_input->>'unit' not in('m','ft') then raise exception 'Invalid unit' using errcode='22023';end if;v_unit:=p_input->>'unit';
  v_cal:=p_input->'calibration';
  if jsonb_typeof(v_cal)='object' then
   if (select array_agg(key order by key) from jsonb_object_keys(v_cal) key) is distinct from array['lengthMilli','points'] then raise exception 'Invalid calibration' using errcode='22023';end if;
   v_points:=public.pro_work_takeoff_points(v_cal->'points',2,2);v_len:=public.pro_work_takeoff_int(v_cal->'lengthMilli',1,1000000);
  elsif jsonb_typeof(v_cal) is distinct from 'null' then raise exception 'Invalid calibration' using errcode='22023';end if;
 elsif act in('measurement_create','measurement_update') then
  v_name:=public.pro_work_takeoff_text(p_input->'name',120);
  if jsonb_typeof(p_input->'color') is distinct from 'string' or not coalesce(p_input->>'color'~'^#[0-9a-f]{6}$',false) then raise exception 'Invalid color' using errcode='22023';end if;v_color:=p_input->>'color';
  if jsonb_typeof(p_input->'categoryId') not in('string','null') or jsonb_typeof(p_input->'productId') not in('string','null') or jsonb_typeof(p_input->'multiplierMode') is distinct from 'string'
   or jsonb_typeof(p_input->'multiplierMilli') not in('number','null') or jsonb_typeof(p_input->'manualMilli') not in('number','null') then raise exception 'Invalid measurement fields' using errcode='22023';end if;
  v_cat:=(p_input->>'categoryId')::uuid;v_product:=p_input->>'productId';
  if v_product is not null and length(v_product) not between 1 and 160 then raise exception 'Invalid item' using errcode='22023';end if;
  v_mode:=p_input->>'multiplierMode';if v_mode not in('none','height','factor') then raise exception 'Invalid multiplier' using errcode='22023';end if;
  if (v_mode='none')<>(jsonb_typeof(p_input->'multiplierMilli')='null') then raise exception 'Invalid multiplier' using errcode='22023';end if;
  if v_mode<>'none' then v_mult:=public.pro_work_takeoff_int(p_input->'multiplierMilli',1,100000000);end if;
  v_waste:=public.pro_work_takeoff_int(p_input->'wasteBps',0,10000);
  if jsonb_typeof(p_input->'manualMilli')='number' then v_manual:=public.pro_work_takeoff_int(p_input->'manualMilli',1,1000000000000);end if;
  if act='measurement_create' then
   if jsonb_typeof(p_input->'kind') is distinct from 'string' or p_input->>'kind' not in('area','length','count') or jsonb_typeof(p_input->'planId') is distinct from 'string' then raise exception 'Invalid measurement kind' using errcode='22023';end if;
   v_kind:=p_input->>'kind';v_plan:=(p_input->>'planId')::uuid;v_page:=public.pro_work_takeoff_int(p_input->'pageNumber',1,200);
  end if;
 elsif act='measurement_visibility' then
  if jsonb_typeof(p_input->'hidden') is distinct from 'boolean' then raise exception 'Invalid visibility' using errcode='22023';end if;
 elsif act='send_estimate' then
  if jsonb_typeof(p_input->'measurementIds') is distinct from 'array' or jsonb_array_length(p_input->'measurementIds') not between 1 and 100
   or exists(select 1 from jsonb_array_elements(p_input->'measurementIds') e where jsonb_typeof(e.value) is distinct from 'string')
   or jsonb_typeof(p_input->'estimateId') not in('string','null') or (jsonb_typeof(p_input->'estimateId')='null')<>(jsonb_typeof(p_input->'estimateRevision')='null')
   or jsonb_typeof(p_input->'language') is distinct from 'string' or p_input->>'language' not in('es','en') then raise exception 'Invalid estimate request' using errcode='22023';end if;
  select array_agg((e.value#>>'{}')::uuid order by e.ord) into ids from jsonb_array_elements(p_input->'measurementIds') with ordinality e(value,ord);
  if (select count(distinct x) from unnest(ids) x)<>cardinality(ids) then raise exception 'Duplicate measurement' using errcode='22023';end if;
  eid:=(p_input->>'estimateId')::uuid;en:=p_input->>'language'='en';
  if eid is not null then rev:=public.pro_work_takeoff_int(p_input->'estimateRevision',1,2147483646)::integer;end if;
 end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-takeoff-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_work_takeoff_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-takeoff:'||p_actor::text||':'||wid,0));
 select * into w from public.pro_work where user_id=p_actor and id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 target:=tid::text;
 if act='plan_create' then
  if exists(select 1 from public.pro_work_takeoff_plans where id=tid) then raise exception 'Plan id already used' using errcode='23505';end if;
  if not exists(select 1 from public.pro_work_files where owner_id=p_actor and work_id=wid and id=v_file and ready and mime_type='image/jpeg') then raise exception 'Unknown plan image' using errcode='22023';end if;
  if exists(select 1 from public.pro_work_takeoff_plans where owner_id=p_actor and file_id=v_file) then raise exception 'File already used as a plan' using errcode='23505';end if;
  if (select count(*) from public.pro_work_takeoff_plans where owner_id=p_actor and work_id=wid)>=50 then raise exception 'Plan limit' using errcode='54000';end if;
  insert into public.pro_work_takeoff_plans(owner_id,id,work_id,file_id,title) values(p_actor,tid,wid,v_file,v_title) returning * into plan;
  insert into public.pro_work_takeoff_pages(owner_id,plan_id,page_number,width_px,height_px) values(p_actor,tid,1,v_w,v_h);
  before_json:=null;after_json:=public.pro_work_takeoff_plan_json(plan);
 elsif tkind='plan' then
  select * into plan from public.pro_work_takeoff_plans where owner_id=p_actor and id=tid and work_id=wid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if plan.revision<>rev then raise exception 'Plan changed' using errcode='40001';end if;
  before_json:=public.pro_work_takeoff_plan_json(plan);
  if act='plan_update' then
   if plan.archived then raise exception 'Restore before editing' using errcode='22023';end if;
   if plan.title=v_title then raise exception 'No plan changes' using errcode='22023';end if;
   update public.pro_work_takeoff_plans set title=v_title,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into plan;
  elsif act='plan_archive' then
   if plan.archived then raise exception 'Already archived' using errcode='22023';end if;
   update public.pro_work_takeoff_plans set archived=true,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into plan;
  else
   if not plan.archived then raise exception 'Not archived' using errcode='22023';end if;
   update public.pro_work_takeoff_plans set archived=false,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into plan;
  end if;
  after_json:=public.pro_work_takeoff_plan_json(plan);
 elsif act='page_calibrate' then
  select * into plan from public.pro_work_takeoff_plans where owner_id=p_actor and id=tid and work_id=wid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if plan.archived then raise exception 'Restore before editing' using errcode='22023';end if;
  select * into pg from public.pro_work_takeoff_pages where owner_id=p_actor and plan_id=tid and page_number=v_page for update;
  if not found then raise exception 'Unknown page' using errcode='22023';end if;
  if pg.revision<>rev then raise exception 'Page changed' using errcode='40001';end if;
  target:=tid::text||':'||v_page;before_json:=public.pro_work_takeoff_page_json(pg);
  if v_points is not null and public.pro_work_takeoff_px_distance((v_points->0->>0)::integer,(v_points->0->>1)::integer,(v_points->1->>0)::integer,(v_points->1->>1)::integer,pg.width_px,pg.height_px)<5 then
   raise exception 'Reference line too short' using errcode='22023';end if;
  if pg.unit=v_unit and pg.cal_length_milli is not distinct from v_len and pg.cal_x1 is not distinct from (v_points->0->>0)::integer and pg.cal_y1 is not distinct from (v_points->0->>1)::integer
   and pg.cal_x2 is not distinct from (v_points->1->>0)::integer and pg.cal_y2 is not distinct from (v_points->1->>1)::integer then raise exception 'No page changes' using errcode='22023';end if;
  update public.pro_work_takeoff_pages set unit=v_unit,cal_x1=(v_points->0->>0)::integer,cal_y1=(v_points->0->>1)::integer,cal_x2=(v_points->1->>0)::integer,cal_y2=(v_points->1->>1)::integer,
   cal_length_milli=v_len,revision=revision+1,updated_at=now() where owner_id=p_actor and plan_id=tid and page_number=v_page returning * into pg;
  -- Recalibrating recomputes every drawn measurement of the page: keep them in range.
  if exists(select 1 from public.pro_work_takeoff_measurements x where x.owner_id=p_actor and x.plan_id=tid and x.page_number=v_page and not x.archived
   and coalesce((public.pro_work_takeoff_result(x,pg)->>'totalMilli')::numeric,0)>1000000000000) then raise exception 'Result too large' using errcode='22023';end if;
  after_json:=public.pro_work_takeoff_page_json(pg);
 elsif act='send_estimate' then
  if coalesce(w.cancelled,false) then raise exception 'Cancelled job' using errcode='22023';end if;
  -- Closing round (security review B2): «an opening is never quoted on its own» is checked here, under the
  -- per-job lock that pro_work_takeoff_deduction_mutate also takes (module takeoff-deductions-local.sql;
  -- called dynamically so this module still installs before it).
  if to_regprocedure('public.pro_work_takeoff_send_check(uuid,text,uuid[])') is not null then
   execute 'select public.pro_work_takeoff_send_check($1,$2,$3)' into sendable using p_actor,wid,ids;
   if sendable is not true then raise exception 'An opening is not quoted on its own' using errcode='22023',hint='pro_takeoff_opening';end if;
  end if;
  -- New draft estimate for this job (deterministic id from the action) or an unshared draft of this job.
  if eid is null then
   eid:=public.pro_work_takeoff_uuid('pro-work-takeoff-estimate:'||p_actor::text||':'||aid::text);created:=true;
   ctx:=public.pro_private_estimate_context(p_actor,null,'work',wid);
   issuer:=ctx->'issuer';
   if coalesce(btrim(issuer->>'issuerName'),'')='' then
    issuer:=jsonb_set(issuer,'{issuerName}',to_jsonb(left(coalesce((select nullif(btrim(business_name),'') from public.professionals where profile_id=p_actor limit 1),(select nullif(btrim(full_name),'') from public.profiles where id=p_actor),'ContrataCR Pro'),160)));
   end if;
   lines:='[]'::jsonb;
  else
   created:=false;
   select * into est from public.pro_private_estimates where owner_id=p_actor and id=eid for update;
   if not found or est.archived or not exists(select 1 from public.pro_project_estimate_rows(p_actor,w) r where r.estimate_id=eid and r.relation='project') then raise exception 'Forbidden' using errcode='42501';end if;
   if exists(select 1 from public.pro_private_estimate_publications v where v.owner_id=p_actor and v.estimate_id=eid) then raise exception 'Estimate already shared' using errcode='22023';end if;
   if est.revision<>rev then raise exception 'Estimate changed' using errcode='40001';end if;
   select coalesce(jsonb_agg(content order by position),'[]'::jsonb) into lines from public.pro_private_estimate_items where owner_id=p_actor and estimate_id=eid;
  end if;
  foreach mid in array ids loop
   select * into m from public.pro_work_takeoff_measurements where owner_id=p_actor and work_id=wid and id=mid;
   if not found then raise exception 'Unknown measurement' using errcode='22023';end if;
   if m.archived or exists(select 1 from public.pro_work_takeoff_plans where owner_id=p_actor and id=m.plan_id and archived) then raise exception 'Archived measurement' using errcode='22023';end if;
   idx:=null;old_line:=null;
   select e.ord-1,e.value into idx,old_line from jsonb_array_elements(lines) with ordinality e(value,ord) where e.value->>'id'=public.pro_work_takeoff_uuid('pro-work-takeoff-line:'||eid::text||':'||mid::text)::text;
   new_line:=public.pro_work_takeoff_line(p_actor,eid,m,old_line,en);
   -- Sending again updates the same line (quantity, unit, description) instead of duplicating it.
   if idx is null then lines:=lines||jsonb_build_array(new_line);else lines:=jsonb_set(lines,array[idx::text],new_line);end if;
   line_ids:=line_ids||jsonb_build_array(new_line->>'id');
  end loop;
  if jsonb_array_length(lines)>100 then raise exception 'Estimate line limit' using errcode='54000';end if;
  if created then
   estimate_input:=jsonb_build_object('action','save','actionId',public.pro_work_takeoff_uuid('pro-work-takeoff-estimate-action:'||aid::text),'estimateId',eid,'revision',0,
    'clientId',ctx->'client'->>'id','refreshClient',false,'clientFingerprint',ctx->>'clientFingerprint','source',ctx->'source','issuer',issuer,
    'title',left(coalesce(nullif(btrim(ctx->>'title'),''),case when en then 'Plan measurements' else 'Mediciones sobre planos' end),160),
    'notes','','currency','CRC','validUntil',null,'lines',lines);
  else
   estimate_input:=jsonb_build_object('action','save','actionId',public.pro_work_takeoff_uuid('pro-work-takeoff-estimate-action:'||aid::text),'estimateId',eid,'revision',est.revision,
    'clientId',est.client_id,'refreshClient',false,'clientFingerprint',md5(est.client_snapshot::text),'source',coalesce(est.source,'null'::jsonb),'issuer',est.issuer,
    'title',est.title,'notes',est.notes,'currency',est.currency,'validUntil',to_jsonb(est.valid_until),'lines',lines);
  end if;
  -- Reuses the private estimate writer: same validation, totals, receipts and history.
  answer:=public.pro_private_estimate_mutate(p_actor,estimate_input);
  target:=eid::text;before_json:=null;
  after_json:=jsonb_build_object('estimateId',eid,'created',created,'estimateRevision',answer->'estimate'->'revision','title',answer->'estimate'->>'title',
   'lineIds',line_ids,'measurementIds',to_jsonb(ids),'lineCount',jsonb_array_length(answer->'estimate'->'lines'),'totalCents',answer->'estimate'->'totalCents','currency',answer->'estimate'->>'currency');
 elsif act='measurement_create' then
  if exists(select 1 from public.pro_work_takeoff_measurements where id=tid) then raise exception 'Measurement id already used' using errcode='23505';end if;
  select * into plan from public.pro_work_takeoff_plans where owner_id=p_actor and id=v_plan and work_id=wid;
  if not found or plan.archived then raise exception 'Unknown plan' using errcode='22023';end if;
  select * into pg from public.pro_work_takeoff_pages where owner_id=p_actor and plan_id=v_plan and page_number=v_page;
  if not found then raise exception 'Unknown page' using errcode='22023';end if;
  if (select count(*) from public.pro_work_takeoff_measurements where owner_id=p_actor and work_id=wid)>=1000 then raise exception 'Measurement limit' using errcode='54000';end if;
  v_kind:=p_input->>'kind';
 else
  select * into m from public.pro_work_takeoff_measurements where owner_id=p_actor and id=tid and work_id=wid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if m.revision<>rev then raise exception 'Measurement changed' using errcode='40001';end if;
  if m.archived and act<>'measurement_restore' then raise exception 'Restore before editing' using errcode='22023';end if;
  if act<>'measurement_restore' and exists(select 1 from public.pro_work_takeoff_plans where owner_id=p_actor and id=m.plan_id and archived) then raise exception 'Restore the plan first' using errcode='22023';end if;
  select * into pg from public.pro_work_takeoff_pages where owner_id=p_actor and plan_id=m.plan_id and page_number=m.page_number;
  before_json:=public.pro_work_takeoff_measurement_json(m);v_kind:=m.kind;
 end if;
 if act in('measurement_create','measurement_update') then
  -- Points: area 3+, length 2+, count 1+; or a value typed by hand (no points).
  if v_manual is not null then
   if jsonb_typeof(p_input->'points') is distinct from 'array' or jsonb_array_length(p_input->'points')<>0 then raise exception 'Manual value without points' using errcode='22023';end if;v_points:='[]'::jsonb;
  else
   v_points:=public.pro_work_takeoff_points(p_input->'points',case v_kind when 'area' then 3 when 'length' then 2 else 1 end,400);
   if v_kind='area' and public.pro_work_takeoff_px_area(v_points,pg.width_px,pg.height_px)=0 then raise exception 'Empty area' using errcode='22023';end if;
  end if;
  if v_mode='height' and v_kind<>'length' then raise exception 'Height only applies to lengths' using errcode='22023';end if;
  if v_cat is not null and v_cat is distinct from m.category_id and not exists(select 1 from public.pro_catalog_organizations where user_id=p_actor and kind='product_category' and id=v_cat and not archived) then raise exception 'Unknown category' using errcode='22023';end if;
  if v_product is not null and v_product is distinct from m.product_id and not exists(select 1 from public.pro_products where user_id=p_actor and id=v_product and not archived) then raise exception 'Unknown item' using errcode='22023';end if;
  if act='measurement_create' then
   insert into public.pro_work_takeoff_measurements(owner_id,id,work_id,plan_id,page_number,kind,name,category_id,color,points,manual_milli,multiplier_mode,multiplier_milli,waste_bps,product_id)
    values(p_actor,tid,wid,v_plan,v_page,v_kind,v_name,v_cat,v_color,v_points,v_manual,v_mode,v_mult,v_waste,v_product) returning * into m;
  else
   if m.name=v_name and m.category_id is not distinct from v_cat and m.color=v_color and m.points=v_points and m.manual_milli is not distinct from v_manual and m.multiplier_mode=v_mode
    and m.multiplier_milli is not distinct from v_mult and m.waste_bps=v_waste and m.product_id is not distinct from v_product then raise exception 'No measurement changes' using errcode='22023';end if;
   update public.pro_work_takeoff_measurements set name=v_name,category_id=v_cat,color=v_color,points=v_points,manual_milli=v_manual,multiplier_mode=v_mode,multiplier_milli=v_mult,
    waste_bps=v_waste,product_id=v_product,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into m;
  end if;
  if coalesce((public.pro_work_takeoff_result(m,pg)->>'totalMilli')::numeric,0)>1000000000000 then raise exception 'Result too large' using errcode='22023';end if;
  after_json:=public.pro_work_takeoff_measurement_json(m);
 elsif act='measurement_visibility' then
  if m.hidden=(p_input->>'hidden')::boolean then raise exception 'No visibility change' using errcode='22023';end if;
  update public.pro_work_takeoff_measurements set hidden=(p_input->>'hidden')::boolean,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into m;
  after_json:=public.pro_work_takeoff_measurement_json(m);
 elsif act='measurement_archive' then
  update public.pro_work_takeoff_measurements set archived=true,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into m;
  after_json:=public.pro_work_takeoff_measurement_json(m);
 elsif act='measurement_restore' then
  if not m.archived then raise exception 'Not archived' using errcode='22023';end if;
  if exists(select 1 from public.pro_work_takeoff_plans where owner_id=p_actor and id=m.plan_id and archived) then raise exception 'Restore the plan first' using errcode='22023';end if;
  update public.pro_work_takeoff_measurements set archived=false,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into m;
  after_json:=public.pro_work_takeoff_measurement_json(m);
 end if;
 result:=jsonb_build_object(tkind,after_json);
 insert into public.pro_work_takeoff_history(owner_id,work_id,action_id,actor_id,action,target_kind,target_id,before_value,after_value) values(p_actor,wid,aid,p_actor,act,tkind,target,before_json,after_json);
 insert into public.pro_work_takeoff_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
create or replace function public.pro_work_takeoff_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Takeoff history and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_work_takeoff_history_immutable on public.pro_work_takeoff_history;
create trigger pro_work_takeoff_history_immutable before update on public.pro_work_takeoff_history for each row execute function public.pro_work_takeoff_immutable();
drop trigger if exists pro_work_takeoff_action_immutable on public.pro_work_takeoff_actions;
create trigger pro_work_takeoff_action_immutable before update on public.pro_work_takeoff_actions for each row execute function public.pro_work_takeoff_immutable();
do $$declare t text;f record;begin
 foreach t in array array['pro_work_takeoff_plans','pro_work_takeoff_pages','pro_work_takeoff_measurements','pro_work_takeoff_history','pro_work_takeoff_actions'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select,insert,update,delete on public.%I to service_role',t);
 end loop;
 grant usage,select on sequence public.pro_work_takeoff_plans_position_seq,public.pro_work_takeoff_measurements_position_seq to service_role;
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.proname like 'pro_work_takeoff%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  if f.proname<>'pro_work_takeoff_immutable' then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$;
notify pgrst,'reload schema';
commit;

-- ===== credits-retainers-local.sql =====
-- LOCAL PRO ONLY. Créditos y anticipos por proyecto (family 50 of the parity register).
-- Internal, NON-FISCAL records: nothing here charges, moves money, sends anything or
-- issues a Hacienda document. Amounts are CRC céntimos (bigint); days are America/Costa_Rica.
--
-- Kinds (per-account gapless numbering per kind): retainer ANT-0001, credit_note NC-0001,
-- overpayment SP-0001 and refund REE-0001.
--
-- Reuse, never a second payments ledger:
--  * A received retainer and an overpayment are always backed by ONE payment of the existing
--    ledger (pro_client_entries kind 'payment'): linking an existing payment, or recording a
--    new one through pro_record_client_operation (manual date/method/reference). The ledger
--    snapshot pro_invoice_payments is created exactly as invoice-payments does.
--  * Applying an entry-backed credit to an invoice draft goes THROUGH
--    pro_invoice_payment_mutate ('apply' / 'unapply'), so the invoice payment panel, the
--    draft balance and pro_invoice_payment_used see it and the same money can never be
--    applied twice by both modules.
--  * A credit note is not money: its applications live in pro_credit_applications only and
--    reduce the draft balance computed by pro_credit_draft_balance.
--  * A refund is a manual record of money returned outside ContrataCR. It does not void the
--    ledger payment (the ledger has no partial voids); it reduces the credit's balance.
--
-- Figures per credit (pro_credit_figures):
--   applied   = Σ active applications (not reverted here, not voided in invoice payments,
--               source payment not reversed in the ledger)
--   refunded  = Σ refunds not voided
--   balance   = amount − applied − refunded        (0 while requested, cancelled or reversed)
--   available = balance, and for entry-backed credits also ≤ the payment's unallocated money
--               (entry amount − every invoice application of that payment) − refunded.
-- Overpayment detection (pro_credit_excess):
--   excess = max(0, ledger paid − net billed − Σ min(amount − applied, payment unallocated)
--            of entry-backed credits),
--   net billed = Σ active drafts (total − credit-note applications) + payments applied to
--   archived drafts.
--
-- Lock order: the owner's advisory lock shared with the ledger, invoice drafts and invoice
-- payments (hashtextextended(owner,0)) -> action receipt -> counter row -> credit row -> draft row.
begin;
create table if not exists public.pro_credit_counters(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 kind text not null check(kind in('retainer','credit_note','overpayment','refund')),
 last_number integer not null default 0 check(last_number between 0 and 999999),
 primary key(owner_id,kind)
);
create table if not exists public.pro_credits(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,work_id text not null,client_id text not null,
 kind text not null check(kind in('retainer','credit_note','overpayment')),
 number integer not null check(number between 1 and 999999),
 title text not null check(length(btrim(title)) between 1 and 160),
 note text check(note is null or length(btrim(note)) between 1 and 2000),
 reason text check(reason is null or length(btrim(reason)) between 1 and 300),
 amount_cents bigint not null check(amount_cents between 1 and 10000000000),
 requested_on date,
 status text not null check(status in('requested','active','cancelled')),
 entry_id uuid,received_on date,method text check(method is null or method in('cash','card','transfer','sinpe','other')),
 reference text check(reference is null or length(reference)<=160),
 received_at timestamptz,cancelled_at timestamptz,cancel_reason text check(cancel_reason is null or length(btrim(cancel_reason)) between 1 and 300),
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,kind,number),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 foreign key(owner_id,client_id) references public.pro_clients(user_id,id) on delete cascade,
 foreign key(owner_id,entry_id) references public.pro_client_entries(user_id,id) on delete cascade,
 check((kind='credit_note')=(reason is not null)),
 check(kind<>'credit_note' or entry_id is null),
 check(kind<>'overpayment' or entry_id is not null),
 check(kind<>'retainer' or requested_on is not null),
 check(kind<>'retainer' or status<>'requested' or entry_id is null),
 check(kind<>'retainer' or status<>'active' or entry_id is not null),
 check(kind='retainer' or status<>'requested'),
 check((entry_id is null)=(received_on is null) and (entry_id is null)=(method is null)),
 check((status='cancelled')=(cancelled_at is not null))
);
create unique index if not exists pro_credit_global_id on public.pro_credits(id);
create unique index if not exists pro_credit_one_per_payment on public.pro_credits(owner_id,entry_id) where entry_id is not null and status<>'cancelled';
create index if not exists pro_credit_page on public.pro_credits(owner_id,work_id,kind,number desc);
-- One row per application action. A reversal is a new row in pro_credit_application_reversals.
create table if not exists public.pro_credit_applications(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,credit_id uuid not null,work_id text not null,draft_id uuid not null,
 amount_cents bigint not null check(amount_cents between 1 and 10000000000),
 invoice_application_id uuid,created_at timestamptz not null default now(),
 primary key(owner_id,id),
 foreign key(owner_id,credit_id) references public.pro_credits(owner_id,id) on delete cascade,
 foreign key(owner_id,draft_id) references public.pro_invoice_drafts(user_id,id) on delete cascade,
 foreign key(owner_id,invoice_application_id) references public.pro_invoice_payment_applications(user_id,id) on delete cascade
);
create unique index if not exists pro_credit_application_invoice on public.pro_credit_applications(owner_id,invoice_application_id) where invoice_application_id is not null;
create index if not exists pro_credit_applications_credit on public.pro_credit_applications(owner_id,credit_id,created_at desc);
create index if not exists pro_credit_applications_draft on public.pro_credit_applications(owner_id,draft_id);
create table if not exists public.pro_credit_application_reversals(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,application_id uuid not null,
 reason text not null check(length(btrim(reason)) between 1 and 300),created_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,application_id),
 foreign key(owner_id,application_id) references public.pro_credit_applications(owner_id,id) on delete cascade
);
create table if not exists public.pro_credit_refunds(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,credit_id uuid not null,work_id text not null,
 number integer not null check(number between 1 and 999999),
 amount_cents bigint not null check(amount_cents between 1 and 10000000000),
 refunded_on date not null,method text not null check(method in('cash','card','transfer','sinpe','other')),
 reference text check(reference is null or length(btrim(reference)) between 1 and 160),
 note text check(note is null or length(btrim(note)) between 1 and 300),
 created_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,number),
 foreign key(owner_id,credit_id) references public.pro_credits(owner_id,id) on delete cascade
);
create index if not exists pro_credit_refund_page on public.pro_credit_refunds(owner_id,work_id,number desc);
create index if not exists pro_credit_refund_credit on public.pro_credit_refunds(owner_id,credit_id);
create table if not exists public.pro_credit_refund_voids(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,refund_id uuid not null,
 reason text not null check(length(btrim(reason)) between 1 and 300),created_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,refund_id),
 foreign key(owner_id,refund_id) references public.pro_credit_refunds(owner_id,id) on delete cascade
);
create table if not exists public.pro_credit_history(
 owner_id uuid not null,work_id text not null,credit_id uuid not null,action_id uuid not null,
 action text not null check(action in('create','receive','update','apply','unapply','refund','void_refund','cancel')),
 before_value jsonb,after_value jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(owner_id,action_id),foreign key(owner_id,credit_id) references public.pro_credits(owner_id,id) on delete cascade
);
create index if not exists pro_credit_history_page on public.pro_credit_history(owner_id,credit_id,at desc);
create table if not exists public.pro_credit_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id)
);

create or replace function public.pro_credit_today() returns date
language sql stable security invoker set search_path=public,pg_temp as $$ select (now() at time zone 'America/Costa_Rica')::date $$;
create or replace function public.pro_credit_code(p_kind text,p_number integer) returns text
language sql immutable security invoker set search_path=public,pg_temp as $$
 select case p_kind when 'retainer' then 'ANT-' when 'credit_note' then 'NC-' when 'overpayment' then 'SP-' else 'REE-' end||lpad(p_number::text,4,'0') $$;

-- Optional text: JSON null or a string trimmed to 1..max (empty → null). Raises 22023 otherwise.
create or replace function public.pro_credit_text(p_value jsonb,p_max integer,p_required boolean) returns text
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare t text;
begin
 if p_value is null or jsonb_typeof(p_value)='null' then if p_required then raise exception 'Missing text' using errcode='22023';end if;return null;end if;
 if jsonb_typeof(p_value)<>'string' then raise exception 'Invalid text' using errcode='22023';end if;
 t:=btrim(p_value#>>'{}');
 if t='' then if p_required then raise exception 'Missing text' using errcode='22023';end if;return null;end if;
 if length(t)>p_max or (p_max<=300 and t~'[[:cntrl:]]') then raise exception 'Invalid text' using errcode='22023';end if;
 return t;
end $$;
create or replace function public.pro_credit_day(p_value jsonb,p_required boolean) returns date
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare d date;
begin
 if p_value is null or jsonb_typeof(p_value)='null' then if p_required then raise exception 'Missing date' using errcode='22023';end if;return null;end if;
 if jsonb_typeof(p_value)<>'string' or not (p_value#>>'{}')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid date' using errcode='22023';end if;
 begin d:=(p_value#>>'{}')::date;exception when others then raise exception 'Invalid date' using errcode='22023';end;
 if to_char(d,'YYYY-MM-DD')<>p_value#>>'{}' or d<date '2000-01-01' then raise exception 'Invalid date' using errcode='22023';end if;
 return d;
end $$;
create or replace function public.pro_credit_amount(p_value jsonb) returns bigint
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare n numeric;
begin
 if p_value is null or jsonb_typeof(p_value)<>'number' then raise exception 'Invalid amount' using errcode='22023';end if;
 n:=(p_value#>>'{}')::numeric;if n<>round(n) or n not between 1 and 10000000000 then raise exception 'Invalid amount' using errcode='22023';end if;
 return n::bigint;
end $$;

-- A ledger payment that was voided (payment_void) no longer backs anything.
create or replace function public.pro_credit_entry_reversed(p_owner uuid,p_entry uuid) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select p_entry is not null and exists(select 1 from public.pro_client_entries r where r.user_id=p_owner and r.reversal_id=p_entry and r.kind='payment_void') $$;
-- Unallocated money of one ledger payment: amount − every active invoice application of it.
create or replace function public.pro_credit_entry_free(p_owner uuid,p_entry uuid) returns bigint
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce((select case when public.pro_credit_entry_reversed(p_owner,e.id) then 0
   else e.amount_cents-coalesce((select public.pro_invoice_payment_used(p_owner,p.id,null) from public.pro_invoice_payments p where p.user_id=p_owner and p.entry_id=e.id),0) end
  from public.pro_client_entries e where e.user_id=p_owner and e.id=p_entry and e.kind='payment'),0)::bigint $$;

-- State of each application of a credit (active, reverted here, voided in invoice payments, source reversed).
create or replace function public.pro_credit_application_rows(p_owner uuid,p_credit uuid)
returns table(id uuid,draft_id uuid,amount_cents bigint,invoice_application_id uuid,created_at timestamptz,state text,reason text,reverted_at timestamptz)
language sql stable security invoker set search_path=public,pg_temp as $$
 select a.id,a.draft_id,a.amount_cents,a.invoice_application_id,a.created_at,
  case when r.id is not null then 'reverted'
   when a.invoice_application_id is not null and exists(select 1 from public.pro_invoice_payment_voids v where v.user_id=a.owner_id and v.application_id=a.invoice_application_id) then 'voided_in_invoice'
   when public.pro_credit_entry_reversed(a.owner_id,c.entry_id) then 'source_reversed' else 'active' end,
  coalesce(r.reason,(select v.reason from public.pro_invoice_payment_voids v where v.user_id=a.owner_id and v.application_id=a.invoice_application_id)),
  coalesce(r.created_at,(select v.created_at from public.pro_invoice_payment_voids v where v.user_id=a.owner_id and v.application_id=a.invoice_application_id))
 from public.pro_credit_applications a join public.pro_credits c on c.owner_id=a.owner_id and c.id=a.credit_id
 left join public.pro_credit_application_reversals r on r.owner_id=a.owner_id and r.application_id=a.id
 where a.owner_id=p_owner and a.credit_id=p_credit $$;

create or replace function public.pro_credit_figures(p_row public.pro_credits,
 out applied_cents bigint,out refunded_cents bigint,out balance_cents bigint,out available_cents bigint,out source_reversed boolean,out display_status text)
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 select coalesce(sum(x.amount_cents) filter(where x.state='active'),0)::bigint into applied_cents from public.pro_credit_application_rows(p_row.owner_id,p_row.id) x;
 select coalesce(sum(f.amount_cents),0)::bigint into refunded_cents from public.pro_credit_refunds f
  where f.owner_id=p_row.owner_id and f.credit_id=p_row.id and not exists(select 1 from public.pro_credit_refund_voids v where v.owner_id=f.owner_id and v.refund_id=f.id);
 source_reversed:=public.pro_credit_entry_reversed(p_row.owner_id,p_row.entry_id);
 if p_row.status<>'active' or source_reversed then balance_cents:=0;available_cents:=0;
 else
  balance_cents:=p_row.amount_cents-applied_cents-refunded_cents;
  available_cents:=greatest(0,balance_cents);
  if p_row.entry_id is not null then available_cents:=greatest(0,least(available_cents,public.pro_credit_entry_free(p_row.owner_id,p_row.entry_id)-refunded_cents));end if;
 end if;
 display_status:=case when p_row.status='cancelled' then 'cancelled' when p_row.status='requested' then 'requested' when source_reversed then 'reversed'
  when available_cents>0 and applied_cents=0 and refunded_cents=0 then 'available' when available_cents>0 then 'partial' else 'used' end;
end $$;

create or replace function public.pro_credit_summary(p_row public.pro_credits) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'workId',p_row.work_id,'kind',p_row.kind,'number',p_row.number,'code',public.pro_credit_code(p_row.kind,p_row.number),
  'title',p_row.title,'status',f.display_status,'baseStatus',p_row.status,'amountCents',p_row.amount_cents,'appliedCents',f.applied_cents,'refundedCents',f.refunded_cents,
  'balanceCents',f.balance_cents,'availableCents',f.available_cents,'sourceReversed',f.source_reversed,
  'recipient',(select c.name from public.pro_clients c where c.user_id=p_row.owner_id and c.id=p_row.client_id),'clientId',p_row.client_id,
  'requestedOn',p_row.requested_on,'entryId',p_row.entry_id,'receivedOn',p_row.received_on,'method',p_row.method,'reference',nullif(p_row.reference,''),
  'reason',p_row.reason,'note',p_row.note,'cancelReason',p_row.cancel_reason,'revision',p_row.revision,
  'createdAt',p_row.created_at,'updatedAt',p_row.updated_at,'receivedAt',p_row.received_at,'cancelledAt',p_row.cancelled_at)
 from public.pro_credit_figures(p_row) f $$;

create or replace function public.pro_credit_refund_json(p_row public.pro_credit_refunds) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'number',p_row.number,'code',public.pro_credit_code('refund',p_row.number),'creditId',p_row.credit_id,
  'creditCode',public.pro_credit_code(c.kind,c.number),'creditKind',c.kind,'title',c.title,'status',case when v.id is null then 'recorded' else 'voided' end,
  'amountCents',p_row.amount_cents,'refundedOn',p_row.refunded_on,'method',p_row.method,'reference',p_row.reference,'note',p_row.note,
  'recipient',(select x.name from public.pro_clients x where x.user_id=c.owner_id and x.id=c.client_id),'voidReason',v.reason,'voidedAt',v.created_at,'createdAt',p_row.created_at)
 from public.pro_credits c left join public.pro_credit_refund_voids v on v.owner_id=p_row.owner_id and v.refund_id=p_row.id
 where c.owner_id=p_row.owner_id and c.id=p_row.credit_id $$;

create or replace function public.pro_credit_json(p_row public.pro_credits) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select public.pro_credit_summary(p_row)||jsonb_build_object(
  'applications',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'draftId',x.draft_id,'draftTitle',d.title,'amountCents',x.amount_cents,
    'viaInvoicePayments',x.invoice_application_id is not null,'state',x.state,'reason',x.reason,'revertedAt',x.reverted_at,'createdAt',x.created_at) order by x.created_at,x.id)
   from public.pro_credit_application_rows(p_row.owner_id,p_row.id) x left join public.pro_invoice_drafts d on d.user_id=p_row.owner_id and d.id=x.draft_id),'[]'::jsonb),
  'refunds',coalesce((select jsonb_agg(public.pro_credit_refund_json(f) order by f.number) from public.pro_credit_refunds f where f.owner_id=p_row.owner_id and f.credit_id=p_row.id),'[]'::jsonb)) $$;

-- Draft balance seen by credits: total − invoice payment applications − credit-note applications.
create or replace function public.pro_credit_note_applied(p_owner uuid,p_draft uuid) returns bigint
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(sum(a.amount_cents),0)::bigint from public.pro_credit_applications a
 where a.owner_id=p_owner and a.draft_id=p_draft and a.invoice_application_id is null
  and not exists(select 1 from public.pro_credit_application_reversals r where r.owner_id=a.owner_id and r.application_id=a.id) $$;
create or replace function public.pro_credit_draft_balance(p_owner uuid,p_draft uuid) returns bigint
language sql stable security invoker set search_path=public,pg_temp as $$
 select d.total_cents-public.pro_invoice_payment_used(p_owner,null,d.id)-public.pro_credit_note_applied(p_owner,d.id)
 from public.pro_invoice_drafts d where d.user_id=p_owner and d.id=p_draft $$;
create or replace function public.pro_credit_draft_archived(p_owner uuid,p_draft uuid) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce((select m.archived from public.pro_invoice_draft_management m where m.user_id=p_owner and m.draft_id=p_draft),false) $$;

create or replace function public.pro_credit_excess(p_owner uuid,p_work text,
 out paid_cents bigint,out billed_cents bigint,out reserved_cents bigint,out excess_cents bigint)
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 paid_cents:=coalesce((public.pro_work_account(p_owner,p_work)->>'paidCents')::bigint,0);
 select coalesce(sum(case when public.pro_credit_draft_archived(p_owner,d.id) then public.pro_invoice_payment_used(p_owner,null,d.id)
   else d.total_cents-public.pro_credit_note_applied(p_owner,d.id) end),0)::bigint into billed_cents
  from public.pro_invoice_drafts d where d.user_id=p_owner and d.work_id=p_work;
 -- What a credit still holds of its payment: never more than the payment's unallocated money.
 select coalesce(sum(least(c.amount_cents-(public.pro_credit_figures(c)).applied_cents,public.pro_credit_entry_free(p_owner,c.entry_id))),0)::bigint into reserved_cents
  from public.pro_credits c where c.owner_id=p_owner and c.work_id=p_work and c.entry_id is not null and c.status='active' and not public.pro_credit_entry_reversed(p_owner,c.entry_id);
 excess_cents:=greatest(0,paid_cents-billed_cents-reserved_cents);
end $$;

create or replace function public.pro_credit_references(p_owner uuid,p_work text,p_client text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object(
  'drafts',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'title',d.title,'totalCents',d.total_cents,
     'paymentsCents',public.pro_invoice_payment_used(p_owner,null,d.id),'creditNotesCents',public.pro_credit_note_applied(p_owner,d.id),
     'balanceCents',public.pro_credit_draft_balance(p_owner,d.id),'createdAt',d.created_at) order by d.created_at desc,d.id)
    from (select * from public.pro_invoice_drafts x where x.user_id=p_owner and x.work_id=p_work and x.client_id=p_client and not public.pro_credit_draft_archived(p_owner,x.id) order by x.created_at desc,x.id limit 100) d),'[]'::jsonb),
  'payments',coalesce((select jsonb_agg(jsonb_build_object('entryId',e.id,'amountCents',e.amount_cents,'freeCents',public.pro_credit_entry_free(p_owner,e.id),'label',e.label,'registeredAt',e.created_at,
     'receivedOn',m.value->'receivedOn','method',m.value->'method','reference',m.value->'reference',
     'hasMetadata',(m.value->>'receivedOn') is not null,
     'creditCode',(select public.pro_credit_code(c.kind,c.number) from public.pro_credits c where c.owner_id=p_owner and c.entry_id=e.id and c.status<>'cancelled')) order by e.position desc)
    from (select * from public.pro_client_entries x where x.user_id=p_owner and x.work_id=p_work and x.client_id=p_client and x.kind='payment'
      and not public.pro_credit_entry_reversed(p_owner,x.id) order by x.position desc limit 100) e
    cross join lateral (select public.pro_invoice_payment_metadata(p_owner,e.id) value) m),'[]'::jsonb)) $$;

create or replace function public.pro_credits_read(p_actor uuid,p_query jsonb) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare wid text;v text;tab text;st text;cur integer;cid uuid;r public.pro_credits;w public.pro_work;cl public.pro_clients;items jsonb;more boolean;totals jsonb;ex record;account jsonb;reason text;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_query) is distinct from 'object' or jsonb_typeof(p_query->'workId') is distinct from 'string'
  or exists(select 1 from jsonb_object_keys(p_query) k where k not in('workId','view','tab','status','after','id'))
  or exists(select 1 from jsonb_each(p_query) e where jsonb_typeof(e.value)<>'string') then
  raise exception 'Invalid credit query' using errcode='22023';end if;
 wid:=p_query->>'workId';v:=coalesce(p_query->>'view','list');
 if length(wid) not between 1 and 160 or v not in('list','detail') then raise exception 'Invalid credit query' using errcode='22023';end if;
 select * into w from public.pro_work x where x.user_id=p_actor and x.id=wid;
 if not found then return null;end if;
 select * into cl from public.pro_clients x where x.user_id=p_actor and x.id=w."clientId";
 if v='detail' then
  if p_query ?| array['tab','status','after'] or p_query->>'id' is null then raise exception 'Credit identity required' using errcode='22023';end if;
  cid:=(p_query->>'id')::uuid;
  select * into r from public.pro_credits x where x.owner_id=p_actor and x.work_id=wid and x.id=cid;
  if not found then return jsonb_build_object('workId',wid,'credit',null);end if;
  return jsonb_build_object('workId',wid,'workTitle',w.service,'today',public.pro_credit_today(),'credit',public.pro_credit_json(r),
   'history',coalesce((select jsonb_agg(jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_value,'after',h.after_value) order by h.at desc,h.action_id)
    from (select * from public.pro_credit_history h where h.owner_id=p_actor and h.credit_id=cid order by h.at desc,h.action_id limit 100) h),'[]'::jsonb));
 end if;
 if p_query ? 'id' then raise exception 'Invalid credit query' using errcode='22023';end if;
 tab:=coalesce(p_query->>'tab','retainer');st:=coalesce(p_query->>'status','all');
 if tab not in('retainer','credit_note','overpayment','refund')
  or (tab<>'refund' and st not in('all','requested','available','partial','used','reversed','cancelled'))
  or (tab='refund' and st not in('all','recorded','voided')) or (tab<>'retainer' and st='requested') then raise exception 'Invalid credit filter' using errcode='22023';end if;
 if p_query->>'after' is not null then if not (p_query->>'after')~'^[0-9]{1,6}$' then raise exception 'Invalid cursor' using errcode='22023';end if;cur:=(p_query->>'after')::integer;end if;
 if tab='refund' then
  with base as materialized(select f.number,public.pro_credit_refund_json(f) s from public.pro_credit_refunds f where f.owner_id=p_actor and f.work_id=wid),
   filtered as(select * from base where st='all' or s->>'status'=st),
   page as(select * from filtered where cur is null or number<cur order by number desc limit 21)
  select coalesce((select jsonb_agg(s order by number desc) from (select * from page order by number desc limit 20) p),'[]'::jsonb),(select count(*)>20 from page),
   jsonb_build_object('count',(select count(*) from base where s->>'status'='recorded'),'totalCents',coalesce((select sum((s->>'amountCents')::bigint) from base where s->>'status'='recorded'),0),
    'appliedCents',0,'availableCents',0,'refundedCents',coalesce((select sum((s->>'amountCents')::bigint) from base where s->>'status'='recorded'),0))
  into items,more,totals;
 else
  with base as materialized(select c.number,public.pro_credit_summary(c) s from public.pro_credits c where c.owner_id=p_actor and c.work_id=wid and c.kind=tab),
   filtered as(select * from base where st='all' or s->>'status'=st),
   page as(select * from filtered where cur is null or number<cur order by number desc limit 21)
  select coalesce((select jsonb_agg(s order by number desc) from (select * from page order by number desc limit 20) p),'[]'::jsonb),(select count(*)>20 from page),
   jsonb_build_object('count',(select count(*) from base where s->>'status'<>'cancelled'),
    'totalCents',coalesce((select sum((s->>'amountCents')::bigint) from base where s->>'status' not in('cancelled','reversed')),0),
    'appliedCents',coalesce((select sum((s->>'appliedCents')::bigint) from base),0),
    'availableCents',coalesce((select sum((s->>'availableCents')::bigint) from base),0),
    'refundedCents',coalesce((select sum((s->>'refundedCents')::bigint) from base),0))
  into items,more,totals;
 end if;
 select * into ex from public.pro_credit_excess(p_actor,wid);
 account:=public.pro_work_account(p_actor,wid);
 reason:=case when coalesce(w.cancelled,false) then 'cancelled' when cl.id is null then 'noClient' when cl.archived then 'archivedClient' end;
 return jsonb_build_object('workId',wid,'workTitle',w.service,'client',case when cl.id is null then null else jsonb_build_object('id',cl.id,'name',cl.name,'archived',cl.archived) end,
  'canWrite',reason is null,'readOnlyReason',reason,'today',public.pro_credit_today(),'tab',tab,
  'items',items,'nextCursor',case when more then (items->19->>'number')::integer end,'totals',totals,
  'tabCounts',jsonb_build_object('retainer',(select count(*) from public.pro_credits where owner_id=p_actor and work_id=wid and kind='retainer'),
   'credit_note',(select count(*) from public.pro_credits where owner_id=p_actor and work_id=wid and kind='credit_note'),
   'overpayment',(select count(*) from public.pro_credits where owner_id=p_actor and work_id=wid and kind='overpayment'),
   'refund',(select count(*) from public.pro_credit_refunds where owner_id=p_actor and work_id=wid)),
  'account',jsonb_build_object('agreedCents',account->'agreedCents','paidCents',coalesce((account->>'paidCents')::bigint,0),'balanceCents',case when account->>'agreedCents' is null then null else account->'balanceCents' end),
  'detection',jsonb_build_object('paidCents',ex.paid_cents,'billedCents',ex.billed_cents,'reservedCents',ex.reserved_cents,'excessCents',ex.excess_cents),
  'nextNumbers',jsonb_build_object('retainer',coalesce((select last_number from public.pro_credit_counters where owner_id=p_actor and kind='retainer'),0)+1,
   'credit_note',coalesce((select last_number from public.pro_credit_counters where owner_id=p_actor and kind='credit_note'),0)+1,
   'overpayment',coalesce((select last_number from public.pro_credit_counters where owner_id=p_actor and kind='overpayment'),0)+1,
   'refund',coalesce((select last_number from public.pro_credit_counters where owner_id=p_actor and kind='refund'),0)+1),
  'references',case when cl.id is null then jsonb_build_object('drafts','[]'::jsonb,'payments','[]'::jsonb) else public.pro_credit_references(p_actor,wid,cl.id) end);
end $$;

-- Links a ledger payment to a credit. Metadata (date/method/reference) comes from the ledger
-- when it already has it; otherwise it is required here and the ledger snapshot is created
-- exactly as invoice-payments would (pro_invoice_payments, id = entry id).
create or replace function public.pro_credit_link_entry(p_owner uuid,p_work text,p_client text,p_entry uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare e public.pro_client_entries;meta jsonb;v_day date;v_method text;v_reference text;
begin
 select * into e from public.pro_client_entries where user_id=p_owner and id=p_entry and kind='payment' and work_id=p_work and client_id=p_client;
 if not found then raise exception 'Choose a payment of this project' using errcode='22023';end if;
 if public.pro_credit_entry_reversed(p_owner,e.id) then raise exception 'Reversed payment' using errcode='22023';end if;
 if exists(select 1 from public.pro_credits where owner_id=p_owner and entry_id=e.id and status<>'cancelled') then raise exception 'Payment already backs a credit' using errcode='22023';end if;
 meta:=public.pro_invoice_payment_metadata(p_owner,e.id);
 if meta->>'receivedOn' is not null then
  if jsonb_typeof(p_input->'receivedOn')<>'null' or jsonb_typeof(p_input->'method')<>'null' or jsonb_typeof(p_input->'reference')<>'null' then raise exception 'Payment details come from the payment' using errcode='22023';end if;
  return jsonb_build_object('receivedOn',meta->>'receivedOn','method',meta->>'method','reference',coalesce(meta->>'reference',''));
 end if;
 v_day:=public.pro_credit_day(p_input->'receivedOn',true);
 if v_day>public.pro_credit_today() then raise exception 'Future received date' using errcode='22023';end if;
 if jsonb_typeof(p_input->'method') is distinct from 'string' or p_input->>'method' not in('cash','card','transfer','sinpe','other') then raise exception 'Invalid method' using errcode='22023';end if;
 v_method:=p_input->>'method';v_reference:=coalesce(public.pro_credit_text(p_input->'reference',160,false),'');
 if not exists(select 1 from public.pro_invoice_payments where user_id=p_owner and entry_id=e.id) then
  insert into public.pro_invoice_payments(user_id,id,client_id,work_id,entry_id,amount_cents,received_on,method,reference) values(p_owner,e.id,p_client,p_work,e.id,e.amount_cents,v_day,v_method,v_reference);
 end if;
 return jsonb_build_object('receivedOn',v_day,'method',v_method,'reference',v_reference);
end $$;

create or replace function public.pro_credits_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;wid text;aid uuid;rid uuid;rev integer;keys text[];expected text[];receipt public.pro_credit_actions;r public.pro_credits;
 before_json jsonb;after_json jsonb;result jsonb;w public.pro_work;cl public.pro_clients;v_title text;v_note text;v_reason text;amount bigint;v_day date;v_method text;v_reference text;
 v_kind text;v_entry uuid;meta jsonb;fig record;ex record;next_number integer;d public.pro_invoice_drafts;state_rev integer;core_rev integer;account jsonb;
 app record;f public.pro_credit_refunds;history_action text;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid credit' using errcode='22023';end if;
 act:=p_input->>'action';
 expected:=case act
  when 'create_retainer' then array['action','actionId','amountCents','id','note','requestedOn','title','workId']
  when 'receive_retainer' then array['action','actionId','amountCents','entryId','id','method','receivedOn','reference','revision','source','workId']
  when 'create_credit_note' then array['action','actionId','amountCents','id','note','reason','title','workId']
  when 'create_overpayment' then array['action','actionId','amountCents','entryId','id','method','note','receivedOn','reference','title','workId']
  when 'update' then array['action','actionId','amountCents','id','note','reason','revision','title','workId']
  when 'apply' then array['action','actionId','amountCents','draftId','id','revision','workId']
  when 'unapply' then array['action','actionId','applicationId','id','reason','revision','workId']
  when 'refund' then array['action','actionId','amountCents','id','method','note','reference','refundedOn','revision','workId']
  when 'void_refund' then array['action','actionId','id','reason','refundId','revision','workId']
  when 'cancel' then array['action','actionId','id','reason','revision','workId'] end;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if expected is null or keys is distinct from expected or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
  or jsonb_typeof(p_input->'id') is distinct from 'string' then raise exception 'Invalid credit fields' using errcode='22023';end if;
 if act not like 'create_%' and (jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646) then raise exception 'Invalid revision' using errcode='22023';end if;
 wid:=p_input->>'workId';aid:=(p_input->>'actionId')::uuid;rid:=(p_input->>'id')::uuid;rev:=case when act not like 'create_%' then (p_input->>'revision')::integer end;
 if length(wid) not between 1 and 160 then raise exception 'Invalid credit identity' using errcode='22023';end if;
 -- Shape validation that needs no state (22023 → 400).
 if act in('create_retainer','create_credit_note','create_overpayment','update') then
  v_title:=public.pro_credit_text(p_input->'title',160,true);v_note:=public.pro_credit_text(p_input->'note',2000,false);amount:=public.pro_credit_amount(p_input->'amountCents');
 end if;
 if act='create_retainer' then v_day:=public.pro_credit_day(p_input->'requestedOn',true);if v_day>public.pro_credit_today()+366 then raise exception 'Invalid requested date' using errcode='22023';end if;
 elsif act='create_credit_note' then v_reason:=public.pro_credit_text(p_input->'reason',300,true);
 elsif act='update' then v_reason:=public.pro_credit_text(p_input->'reason',300,false);
 elsif act in('create_overpayment','receive_retainer') then
  if act='receive_retainer' then
   amount:=public.pro_credit_amount(p_input->'amountCents');
   if jsonb_typeof(p_input->'source') is distinct from 'string' or p_input->>'source' not in('existing','manual') then raise exception 'Invalid source' using errcode='22023';end if;
  end if;
  if coalesce(p_input->>'source','existing')='existing' then
   if jsonb_typeof(p_input->'entryId') is distinct from 'string' then raise exception 'Choose a payment' using errcode='22023';end if;
   v_entry:=(p_input->>'entryId')::uuid;
  else
   if jsonb_typeof(p_input->'entryId') is distinct from 'null' then raise exception 'A manual receipt has no payment' using errcode='22023';end if;
   v_day:=public.pro_credit_day(p_input->'receivedOn',true);if v_day>public.pro_credit_today() then raise exception 'Future received date' using errcode='22023';end if;
   if jsonb_typeof(p_input->'method') is distinct from 'string' or p_input->>'method' not in('cash','card','transfer','sinpe','other') then raise exception 'Invalid method' using errcode='22023';end if;
   v_method:=p_input->>'method';v_reference:=public.pro_credit_text(p_input->'reference',160,false);
  end if;
  if jsonb_typeof(p_input->'receivedOn') not in('string','null') or jsonb_typeof(p_input->'method') not in('string','null') or jsonb_typeof(p_input->'reference') not in('string','null') then raise exception 'Invalid payment details' using errcode='22023';end if;
 elsif act='apply' then amount:=public.pro_credit_amount(p_input->'amountCents');if jsonb_typeof(p_input->'draftId') is distinct from 'string' then raise exception 'Choose an invoice draft' using errcode='22023';end if;
 elsif act='unapply' then v_reason:=public.pro_credit_text(p_input->'reason',160,true);if jsonb_typeof(p_input->'applicationId') is distinct from 'string' then raise exception 'Invalid application' using errcode='22023';end if;
 elsif act='refund' then
  amount:=public.pro_credit_amount(p_input->'amountCents');v_day:=public.pro_credit_day(p_input->'refundedOn',true);
  if v_day>public.pro_credit_today() then raise exception 'Future refund date' using errcode='22023';end if;
  if jsonb_typeof(p_input->'method') is distinct from 'string' or p_input->>'method' not in('cash','card','transfer','sinpe','other') then raise exception 'Invalid method' using errcode='22023';end if;
  v_method:=p_input->>'method';v_reference:=public.pro_credit_text(p_input->'reference',160,false);v_note:=public.pro_credit_text(p_input->'note',300,false);
 elsif act='void_refund' then v_reason:=public.pro_credit_text(p_input->'reason',300,true);if jsonb_typeof(p_input->'refundId') is distinct from 'string' then raise exception 'Invalid refund' using errcode='22023';end if;
 elsif act='cancel' then v_reason:=public.pro_credit_text(p_input->'reason',300,false);
 end if;
 select * into w from public.pro_work where user_id=p_actor and id=wid;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 -- Same owner lock as the ledger, invoice drafts and invoice payments: one writer at a time.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 select * into receipt from public.pro_credit_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 select * into cl from public.pro_clients where user_id=p_actor and id=w."clientId";
 if act like 'create_%' then
  if coalesce(w.cancelled,false) then raise exception 'Restore the job first' using errcode='22023';end if;
  if cl.id is null or cl.archived then raise exception 'The job needs an active customer' using errcode='22023';end if;
  v_kind:=case act when 'create_retainer' then 'retainer' when 'create_credit_note' then 'credit_note' else 'overpayment' end;
  if exists(select 1 from public.pro_credits where id=rid) then raise exception 'Credit id already used' using errcode='23505';end if;
  if (select count(*) from public.pro_credits where owner_id=p_actor and work_id=wid and kind=v_kind)>=500 then raise exception 'Credit limit' using errcode='54000';end if;
  if v_kind='overpayment' then
   select * into ex from public.pro_credit_excess(p_actor,wid);
   meta:=public.pro_credit_link_entry(p_actor,wid,cl.id,v_entry,p_input);
   if amount>least(ex.excess_cents,public.pro_credit_entry_free(p_actor,v_entry)) then raise exception 'Amount exceeds the detected overpayment' using errcode='22023';end if;
  end if;
  -- Per-account number per kind: the counter row lock serializes creators and a failed
  -- transaction rolls the counter back too, so numbers never have gaps.
  insert into public.pro_credit_counters(owner_id,kind) values(p_actor,v_kind) on conflict(owner_id,kind) do nothing;
  update public.pro_credit_counters set last_number=last_number+1 where owner_id=p_actor and kind=v_kind returning last_number into next_number;
  insert into public.pro_credits(owner_id,id,work_id,client_id,kind,number,title,note,reason,amount_cents,requested_on,status,entry_id,received_on,method,reference,received_at)
   values(p_actor,rid,wid,cl.id,v_kind,next_number,v_title,v_note,v_reason,amount,case when v_kind='retainer' then v_day end,
    case when v_kind='retainer' then 'requested' else 'active' end,v_entry,(meta->>'receivedOn')::date,meta->>'method',meta->>'reference',case when v_kind='overpayment' then now() end)
   returning * into r;
  before_json:=null;history_action:='create';
 else
  select * into r from public.pro_credits where owner_id=p_actor and id=rid and work_id=wid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if r.revision<>rev then raise exception 'Credit changed' using errcode='40001';end if;
  before_json:=public.pro_credit_json(r);
  select * into fig from public.pro_credit_figures(r);
  history_action:=act;
  if act='receive_retainer' then
   history_action:='receive';
   if r.kind<>'retainer' or r.status<>'requested' then raise exception 'Only requested retainers can be received' using errcode='22023';end if;
   if coalesce(w.cancelled,false) or cl.id is null or cl.archived or cl.id<>r.client_id then raise exception 'The job needs its active customer' using errcode='22023';end if;
   if p_input->>'source'='existing' then
    meta:=public.pro_credit_link_entry(p_actor,wid,r.client_id,v_entry,p_input);
    if amount>public.pro_credit_entry_free(p_actor,v_entry) then raise exception 'Amount exceeds the unallocated payment' using errcode='22023';end if;
   else
    -- Manual receipt: record the payment in the existing ledger (no second ledger), then its snapshot.
    account:=public.pro_work_account(p_actor,wid);
    if account->>'agreedCents' is null then raise exception 'Set the job agreement before recording a payment' using errcode='22023';end if;
    if amount>(account->>'balanceCents')::bigint then raise exception 'Payment exceeds the job balance' using errcode='22023';end if;
    select revision into core_rev from public.pro_workspace_core where user_id=p_actor for update;
    if core_rev is null then raise exception 'Workspace not ready' using errcode='22023';end if;
    perform public.pro_record_client_operation(p_actor,jsonb_build_object('actionId',aid,'clientId',r.client_id,'workId',wid,'kind','payment','amountCents',amount,
     'note',left(public.pro_credit_code(r.kind,r.number)||' · '||r.title,160)),core_rev);
    insert into public.pro_invoice_payments(user_id,id,client_id,work_id,entry_id,amount_cents,received_on,method,reference)
     values(p_actor,aid,r.client_id,wid,aid,amount,v_day,v_method,coalesce(v_reference,''));
    v_entry:=aid;meta:=jsonb_build_object('receivedOn',v_day,'method',v_method,'reference',coalesce(v_reference,''));
   end if;
   update public.pro_credits set status='active',entry_id=v_entry,amount_cents=amount,received_on=(meta->>'receivedOn')::date,method=meta->>'method',reference=meta->>'reference',
    received_at=now(),revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='update' then
   if r.status='cancelled' then raise exception 'Cancelled credit' using errcode='22023';end if;
   if (r.kind='credit_note')<>(v_reason is not null) then raise exception 'Only credit notes carry a reason' using errcode='22023';end if;
   if r.entry_id is not null and amount<>r.amount_cents then raise exception 'The amount comes from the payment' using errcode='22023';end if;
   if amount<fig.applied_cents+fig.refunded_cents then raise exception 'Amount below applied and refunded' using errcode='22023';end if;
   update public.pro_credits set title=v_title,note=v_note,reason=v_reason,amount_cents=amount,revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
   if before_json-'revision'-'updatedAt'=public.pro_credit_json(r)-'revision'-'updatedAt' then raise exception 'No credit changes' using errcode='22023';end if;
  elsif act='apply' then
   if r.status<>'active' or fig.source_reversed then raise exception 'Credit not available' using errcode='22023';end if;
   if coalesce(w.cancelled,false) or cl.id is null or cl.archived or cl.id<>r.client_id then raise exception 'The job needs its active customer' using errcode='22023';end if;
   select * into d from public.pro_invoice_drafts where user_id=p_actor and id=(p_input->>'draftId')::uuid for update;
   if not found or d.work_id is distinct from wid or d.client_id<>r.client_id then raise exception 'Choose an invoice draft of this project and customer' using errcode='22023';end if;
   if public.pro_credit_draft_archived(p_actor,d.id) then raise exception 'Restore the archived draft first' using errcode='22023';end if;
   if amount>fig.available_cents then raise exception 'Amount exceeds the available credit' using errcode='22023';end if;
   if amount>public.pro_credit_draft_balance(p_actor,d.id) then raise exception 'Amount exceeds the draft balance' using errcode='22023';end if;
   if r.entry_id is not null then
    -- Money already received: allocate it through invoice payments so both modules share one allocation.
    select coalesce((select s.revision from public.pro_invoice_payment_state s where s.user_id=p_actor and s.draft_id=d.id),0) into state_rev;
    perform public.pro_invoice_payment_mutate(p_actor,jsonb_build_object('requestId',aid,'action','apply','draftId',d.id,'draftRevision',d.revision,'revision',state_rev,
     'amountCents',amount,'source','existing','candidateId',r.entry_id));
    insert into public.pro_credit_applications(owner_id,id,credit_id,work_id,draft_id,amount_cents,invoice_application_id) values(p_actor,aid,rid,wid,d.id,amount,aid);
   else
    insert into public.pro_credit_applications(owner_id,id,credit_id,work_id,draft_id,amount_cents) values(p_actor,aid,rid,wid,d.id,amount);
   end if;
   update public.pro_credits set revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='unapply' then
   select * into app from public.pro_credit_application_rows(p_actor,rid) x where x.id=(p_input->>'applicationId')::uuid;
   if not found or app.state<>'active' then raise exception 'Application is not active' using errcode='22023';end if;
   if app.invoice_application_id is not null then
    select * into d from public.pro_invoice_drafts where user_id=p_actor and id=app.draft_id for update;
    select coalesce((select s.revision from public.pro_invoice_payment_state s where s.user_id=p_actor and s.draft_id=d.id),0) into state_rev;
    perform public.pro_invoice_payment_mutate(p_actor,jsonb_build_object('requestId',aid,'action','unapply','draftId',d.id,'draftRevision',d.revision,'revision',state_rev,
     'id',app.invoice_application_id,'reason',v_reason));
   end if;
   insert into public.pro_credit_application_reversals(owner_id,id,application_id,reason) values(p_actor,aid,app.id,v_reason);
   update public.pro_credits set revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='refund' then
   if r.status<>'active' or fig.source_reversed then raise exception 'Credit not available' using errcode='22023';end if;
   if amount>fig.available_cents then raise exception 'Refund exceeds the available credit' using errcode='22023';end if;
   if v_day<coalesce(r.received_on,(r.created_at at time zone 'America/Costa_Rica')::date) then raise exception 'Refund before the credit' using errcode='22023';end if;
   insert into public.pro_credit_counters(owner_id,kind) values(p_actor,'refund') on conflict(owner_id,kind) do nothing;
   update public.pro_credit_counters set last_number=last_number+1 where owner_id=p_actor and kind='refund' returning last_number into next_number;
   insert into public.pro_credit_refunds(owner_id,id,credit_id,work_id,number,amount_cents,refunded_on,method,reference,note) values(p_actor,aid,rid,wid,next_number,amount,v_day,v_method,v_reference,v_note);
   update public.pro_credits set revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='void_refund' then
   select * into f from public.pro_credit_refunds where owner_id=p_actor and credit_id=rid and id=(p_input->>'refundId')::uuid;
   if not found or exists(select 1 from public.pro_credit_refund_voids where owner_id=p_actor and refund_id=f.id) then raise exception 'Refund is not active' using errcode='22023';end if;
   insert into public.pro_credit_refund_voids(owner_id,id,refund_id,reason) values(p_actor,aid,f.id,v_reason);
   update public.pro_credits set revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='cancel' then
   if r.status='cancelled' then raise exception 'Already cancelled' using errcode='22023';end if;
   if fig.applied_cents<>0 or fig.refunded_cents<>0 then raise exception 'Revert applications and refunds before cancelling' using errcode='22023';end if;
   update public.pro_credits set status='cancelled',cancelled_at=now(),cancel_reason=v_reason,revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  end if;
 end if;
 -- Server invariants, checked after every write: never a negative balance, applied ≤ amount.
 select * into fig from public.pro_credit_figures(r);
 if r.status='active' and not fig.source_reversed and (fig.balance_cents<0 or fig.available_cents<0) then raise exception 'Credit balance would be negative' using errcode='23514';end if;
 if act='apply' and public.pro_credit_draft_balance(p_actor,d.id)<0 then raise exception 'Draft balance would be negative' using errcode='23514';end if;
 after_json:=public.pro_credit_json(r);result:=jsonb_build_object('credit',after_json);
 insert into public.pro_credit_history(owner_id,work_id,credit_id,action_id,action,before_value,after_value) values(p_actor,wid,rid,aid,history_action,before_json,after_json);
 insert into public.pro_credit_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- Deferred guard on the module's own tables: whoever writes them, a credit never ends with
-- applied + refunded above its amount and a draft never ends below zero.
create or replace function public.pro_credit_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare c public.pro_credits;fig record;v_credit uuid;v_draft uuid;row_json jsonb:=to_jsonb(new);
begin
 -- NEW is read through jsonb: the same function serves three tables with different columns.
 v_credit:=case when tg_table_name='pro_credits' then (row_json->>'id')::uuid else (row_json->>'credit_id')::uuid end;
 select * into c from public.pro_credits where owner_id=(row_json->>'owner_id')::uuid and id=v_credit;
 if c.id is not null and c.status='active' then
  select * into fig from public.pro_credit_figures(c);
  if not fig.source_reversed and c.amount_cents<fig.applied_cents+fig.refunded_cents then raise exception 'Credit applied above its amount' using errcode='23514';end if;
 elsif c.id is not null and tg_table_name<>'pro_credits' then raise exception 'Credit not active' using errcode='23514';
 end if;
 if tg_table_name='pro_credit_applications' then
  v_draft:=(row_json->>'draft_id')::uuid;
  if public.pro_credit_draft_balance(c.owner_id,v_draft)<0 then raise exception 'Draft balance below zero' using errcode='23514';end if;
 end if;
 return null;
end $$;
drop trigger if exists pro_credit_guard on public.pro_credits;
create constraint trigger pro_credit_guard after update on public.pro_credits deferrable initially deferred for each row execute function public.pro_credit_guard();
drop trigger if exists pro_credit_guard on public.pro_credit_applications;
create constraint trigger pro_credit_guard after insert on public.pro_credit_applications deferrable initially deferred for each row execute function public.pro_credit_guard();
drop trigger if exists pro_credit_guard on public.pro_credit_refunds;
create constraint trigger pro_credit_guard after insert on public.pro_credit_refunds deferrable initially deferred for each row execute function public.pro_credit_guard();

create or replace function public.pro_credit_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Credit history, applications and refunds are immutable' using errcode='23514';
end $$;
do $$declare t text;begin
 foreach t in array array['pro_credit_applications','pro_credit_application_reversals','pro_credit_refunds','pro_credit_refund_voids','pro_credit_history','pro_credit_actions'] loop
  execute format('drop trigger if exists pro_credit_immutable on public.%I',t);
  execute format('create trigger pro_credit_immutable before update on public.%I for each row execute function public.pro_credit_immutable()',t);
 end loop;
end $$;

do $$declare t text;f record;begin
 foreach t in array array['pro_credit_counters','pro_credits','pro_credit_applications','pro_credit_application_reversals','pro_credit_refunds','pro_credit_refund_voids','pro_credit_history','pro_credit_actions'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select,insert,update,delete on public.%I to service_role',t);
 end loop;
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and (p.proname like 'pro\_credit\_%' or p.proname like 'pro\_credits\_%') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  if f.proname not in('pro_credit_immutable','pro_credit_guard','pro_credit_existing_guard') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$;
notify pgrst,'reload schema';
commit;

-- ===== credits-retainers-guard-local.sql =====
-- Local-only guard for credits & retainers (parity register row 50), applied by the leader's decision
-- on 2026-11-11 (phase 2). It attaches deferred constraint triggers to EXISTING tables
-- (pro_invoice_payment_applications, pro_invoice_drafts) so that the existing writers (invoice payments,
-- draft total edits) respect the credits invariant at commit time: a draft cannot end covered above its
-- total by payments + credit notes, and a payment cannot reuse money a credit already refunded.
-- Behaviour without credits is unchanged (both checks are no-ops when no credit rows exist).
-- QA fase 2 (P1-1): both raises keep 22023 (so every existing route still answers 400) and add a
-- HINT ('pro_credit_notes_balance' / 'pro_credit_refunded') that routes translate to clear ES/EN text.
-- Requires credits-retainers-local.sql, invoice-drafts-local.sql and invoice-payments-local.sql. Idempotent.
begin;
create or replace function public.pro_credit_existing_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare row_json jsonb:=to_jsonb(new);v_owner uuid:=(row_json->>'user_id')::uuid;v_draft uuid;v_entry uuid;refunded bigint;
begin
 v_draft:=case when tg_table_name='pro_invoice_drafts' then (row_json->>'id')::uuid else (row_json->>'draft_id')::uuid end;
 if exists(select 1 from public.pro_credit_applications a where a.owner_id=v_owner and a.draft_id=v_draft and a.invoice_application_id is null)
  and public.pro_credit_draft_balance(v_owner,v_draft)<0 then raise exception 'Invoice total is below payments and credit notes' using errcode='22023',hint='pro_credit_notes_balance';end if;
 if tg_table_name='pro_invoice_payment_applications' then
  select p.entry_id into v_entry from public.pro_invoice_payments p where p.user_id=v_owner and p.id=(row_json->>'payment_id')::uuid;
  if v_entry is not null and exists(select 1 from public.pro_credits c where c.owner_id=v_owner and c.entry_id=v_entry and c.status='active') then
   select coalesce(sum(f.amount_cents),0) into refunded from public.pro_credit_refunds f join public.pro_credits c on c.owner_id=f.owner_id and c.id=f.credit_id
    where c.owner_id=v_owner and c.entry_id=v_entry and not exists(select 1 from public.pro_credit_refund_voids v where v.owner_id=f.owner_id and v.refund_id=f.id);
   if public.pro_credit_entry_free(v_owner,v_entry)-refunded<0 then raise exception 'Payment already refunded through a credit' using errcode='22023',hint='pro_credit_refunded';end if;
  end if;
 end if;
 return null;
end $$;
drop trigger if exists pro_credit_existing_guard on public.pro_invoice_payment_applications;
create constraint trigger pro_credit_existing_guard after insert on public.pro_invoice_payment_applications deferrable initially deferred for each row execute function public.pro_credit_existing_guard();
drop trigger if exists pro_credit_existing_guard on public.pro_invoice_drafts;
create constraint trigger pro_credit_existing_guard after update on public.pro_invoice_drafts deferrable initially deferred for each row execute function public.pro_credit_existing_guard();
revoke all on function public.pro_credit_existing_guard() from public,anon,authenticated;
commit;
